        'ms365_intune_heading' => 'Intune - ഉപകരണങ്ങൾ, അവയുടെ പ്രൈമറി ഉപയോക്താക്കൾ, ആപ്പുകൾ',
        'ms365_intune_intro' => 'Intune-ലെ ഉപകരണങ്ങൾ ആസ്തികളാകുന്നു, അവയുടെ പ്രൈമറി ഉപയോക്താവിന്റെ കൈവശമായി, ഇൻസ്റ്റാൾ ചെയ്ത ആപ്പുകളോടൊപ്പം. ഇവിടെ സെറ്റപ്പ് ചെയ്യുക; ഇത് മുമ്പ് Assets -> Settings -> Intune ആയിരുന്നു.',
        'ms365_job_last' => '{job}: {when}, {outcome}',
        'ms365_job_never' => '{job}: ഒരിക്കലും പ്രവർത്തിപ്പിച്ചിട്ടില്ല',
        'ms365_more_heading' => 'Microsoft-ൽ നിന്ന് മറ്റുള്ളവയും',
        'ms365_more_intro' => 'Microsoft 365-മായി സംസാരിക്കുന്ന മറ്റെല്ലാം. ഓരോന്നും അതതിന്റെ സ്ഥാനത്ത് സെറ്റപ്പ് ചെയ്യുന്നു - ബട്ടൺ അത് അവിടെ തുറക്കും - എല്ലാം ഒരിടത്ത് കാണാൻ ഇവിടെ പട്ടികപ്പെടുത്തിയിരിക്കുന്നു.',
        'ms365_open' => 'തുറക്കുക',
