        'ms365_cal_meta' => 'കണക്ഷനുകൾ: {n} - അനലിസ്റ്റുകളുടെ കലണ്ടറുകൾ Outlook-മായി സമന്വയിപ്പിച്ച് നിലനിർത്തുന്നു',
        'ms365_cal_none' => 'Outlook കണക്ഷൻ ഇല്ല',
        'ms365_cal_where' => 'System -> Calendar sync-ന് കീഴിൽ സെറ്റപ്പ് ചെയ്യുക.',
        'ms365_alerts_name' => 'Teams ചാനൽ അലേർട്ടുകൾ',
        'ms365_alerts_meta' => 'ചാനലുകൾ: {n} - സർവീസ് ഡെസ്ക് അലേർട്ടുകൾ കാർഡുകളായി പോസ്റ്റ് ചെയ്യുന്നു',
        'ms365_alerts_none' => 'Teams ചാനൽ ഇല്ല',
