        'ms365_chat_meta' => 'ചാനലുകൾ: {n} - ടിക്കറ്റുകളായി മാറുന്ന Teams-ലെ സംഭാഷണങ്ങൾ',
        'ms365_chat_none' => 'Teams ചാറ്റ് ചാനൽ ഇല്ല',
