        'ms365_intune_tab_connection' => 'കണക്ഷൻ',
        'ms365_intune_tab_import' => 'ഇംപോർട്ട്',
        'ms365_intune_conn_subtitle' => 'ഏത് Microsoft ടെനന്റ്, ഏത് ആപ്പ് രജിസ്ട്രേഷൻ അതിന്റെ ഉപകരണങ്ങൾ വായിക്കുന്നു. എന്ത് ഇംപോർട്ട് ചെയ്യുന്നു എന്നത് ഇംപോർട്ടിൽ സെറ്റപ്പ് ചെയ്യുന്നു.',
        'ms365_intune_import_subtitle' => 'കണക്ഷൻ എന്ത് കൊണ്ടുവരുന്നു: ആസ്തികളായി ഉപകരണങ്ങൾ, ഓരോ തരം ഉപകരണത്തിന്റെയും ആസ്തി തരം, അവയുടെ ഇൻസ്റ്റാൾ ചെയ്ത ആപ്പുകൾ.',
        'ms365_intune_next_import' => 'അടുത്തത്',
        'ms365_intune_assets_off' => 'Intune ഉപകരണങ്ങളെ ആസ്തികളായി കൊണ്ടുവരുന്നു, ഈ ഇൻസ്റ്റാളേഷനിൽ ആസ്തികൾ ഓഫാണ്. Intune സെറ്റപ്പ് ചെയ്യാൻ System -> Modules-ന് കീഴിൽ അത് ഓണാക്കുക.',
        'ms365_intune_tab_devices' => 'ഉപകരണങ്ങൾ',
        'ms365_intune_tab_types' => 'ആസ്തി തരങ്ങൾ',
        'ms365_intune_tab_software' => 'സോഫ്റ്റ്‌വെയർ',
        'ms365_intune_devices_intro' => 'ഓരോ Intune ഉപകരണവും ഒരു ആസ്തിയാകുന്നു, അല്ലെങ്കിൽ ലിങ്ക് ചെയ്തിരിക്കുന്നതിനെ അപ്ഡേറ്റ് ചെയ്യുന്നു. അത് ഏത് കമ്പനിയുടേതാണെന്നും ഒരു സിങ്കിന് അതിൽ എന്ത് മാറ്റാമെന്നും ഇവ തീരുമാനിക്കുന്നു.',
        'ms365_intune_save_hint' => 'എല്ലാ ടാബുകളും സംരക്ഷിക്കുന്നു. കണക്ഷൻ അതിന്റെ സ്വന്തം പേജിൽ സംരക്ഷിക്കുന്നു.',
        'ms365_intune_device_sync' => 'ഉപകരണ സിങ്ക്',
        'ms365_open_intune_conn' => 'കണക്ഷൻ',
        'ms365_open_intune_import' => 'ഇംപോർട്ട്',
        'zabbix_blurb' => 'മോണിറ്ററിംഗ് പ്രശ്നങ്ങൾ സ്വയം incident-കൾ തുറക്കുന്നു, ആവർത്തനങ്ങൾ അവയിൽ ചേർക്കുന്നു, റിക്കവറികൾ അവ പരിഹരിക്കുന്നു.',
        'zabbix_intro' => 'Zabbix ഒരു പ്രശ്നം കണ്ടെത്തുമ്പോൾ - ഡിസ്ക് നിറയുന്നത്, സെർവർ പ്രതികരിക്കാത്തത് - അത് ഇവിടെ ഒരു incident ഉയർത്തുന്നു, CMDB-യിലെ ആ സെർവറുമായി ലിങ്ക് ചെയ്ത്. അതേ പ്രശ്നം വീണ്ടും റിപ്പോർട്ട് ചെയ്താൽ, അത് അതേ ടിക്കറ്റിൽ ചേരും. പ്രശ്നം മാറുമ്പോൾ ടിക്കറ്റ് പരിഹരിക്കപ്പെടുന്നു.',
        'zabbix_direction' => 'Zabbix FreeITSM-നെ വിളിക്കുന്നു - FreeITSM ഒരിക്കലും Zabbix-ലേക്ക് കണക്ട് ചെയ്യുന്നില്ല, അതിനാൽ Zabbix-ന്റെ വിലാസമോ Zabbix പാസ്‌വേഡോ ആവശ്യമില്ല. Zabbix-ന് വേണ്ടതെല്ലാം താഴെയുണ്ട്.',
        'zabbix_not_ready' => 'ആദ്യം System → Database Verification പ്രവർത്തിപ്പിക്കുക: ഈ ഇന്റഗ്രേഷൻ അതിന്റെ ഇവന്റ് ലോഗ് സൂക്ഷിക്കുന്ന പട്ടിക അത് സൃഷ്ടിക്കുന്നു.',
        'zabbix_connect' => 'Zabbix കണക്ട് ചെയ്യുക',
        'zabbix_connect_body' => 'Zabbix ഓരോ അലേർട്ടും താഴെയുള്ള വിലാസത്തിലേക്ക് സീക്രട്ട് ടോക്കണോടൊപ്പം അയയ്ക്കുന്നു. Zabbix-ൽ Alerts → Media types → Create media type എന്നതിലേക്ക് പോകുക, Webhook തിരഞ്ഞെടുക്കുക, FreeITSM എന്ന് പേര് നൽകുക, താഴെയുള്ള പാരാമീറ്ററുകളും സ്ക്രിപ്റ്റും പേസ്റ്റ് ചെയ്യുക, തുടർന്ന് അത് ഒരു ഉപയോക്താവിനും Alerts → Actions → Trigger actions-ലെ ഒരു action-നും ചേർക്കുക. action-ൽ "Recovery operations" ടിക്ക് ചെയ്യുക, ഇല്ലെങ്കിൽ ടിക്കറ്റുകൾ ഒരിക്കലും പരിഹരിക്കപ്പെടില്ല.',
        'zabbix_endpoint' => 'FreeITSM-ന്റെ വിലാസം (ഇത് Zabbix-ന് നൽകുക)',
        'zabbix_import' => 'ഏറ്റവും എളുപ്പം: Zabbix-ലേക്ക് ഇംപോർട്ട് ചെയ്യുക',
        'zabbix_import_body' => 'എല്ലാം പൂരിപ്പിച്ച media type ഡൗൺലോഡ് ചെയ്യുക - മുകളിലെ വിലാസം, നിങ്ങളുടെ ടോക്കൺ, സ്ക്രിപ്റ്റ്, മൂന്ന് സന്ദേശ ടെംപ്ലേറ്റുകൾ - തുടർന്ന് Zabbix-ൽ Alerts → Media types → Import എന്നതിലേക്ക് പോയി ഫയൽ തിരഞ്ഞെടുക്കുക. അതിനുശേഷം അത് ഒരു ഉപയോക്താവിന് നൽകി ഒരു action ചേർക്കുക (ഗൈഡിലെ 4-ാം ഘട്ടം).',
        'zabbix_import_download' => 'Zabbix ഇംപോർട്ടിനായി ഡൗൺലോഡ് ചെയ്യുക',
        'zabbix_import_needs_token' => 'ആദ്യം ഒരു ടോക്കൺ ഉണ്ടാക്കുക - ഫയൽ അത് വഹിക്കുന്നു.',
        'zabbix_by_hand' => 'അല്ലെങ്കിൽ കൈകൊണ്ട് സെറ്റപ്പ് ചെയ്യുക',
        'zabbix_token' => 'ടോക്കൺ',
        'zabbix_token_none' => 'ഇതുവരെ ടോക്കൺ ഇല്ല - ഇന്റഗ്രേഷൻ ഓണാക്കാൻ ഒന്ന് ഉണ്ടാക്കുക.',
        'zabbix_token_make' => 'ടോക്കൺ ഉണ്ടാക്കുക',
        'zabbix_token_rotate' => 'പുതിയ ടോക്കൺ',
        'zabbix_rotate_confirm' => 'പുതിയ ടോക്കൺ ഉണ്ടാക്കണോ? പഴയത് ഉടനടി പ്രവർത്തിക്കുന്നത് നിർത്തും, അതിനാൽ പുതിയത് അതിന്റെ media type-ൽ പേസ്റ്റ് ചെയ്യുന്നതുവരെ Zabbix പരാജയപ്പെടും.',
        'zabbix_params' => 'Media type പാരാമീറ്ററുകൾ',
        'zabbix_params_hint' => 'ഒരു പുതിയ webhook-നായി Zabbix പൂരിപ്പിക്കുന്ന പാരാമീറ്ററുകൾ (URL, HTTPProxy, To, Subject, Message) ഇല്ലാതാക്കുക - അവ അതിന്റെ ഉദാഹരണ സ്ക്രിപ്റ്റിന്റേതാണ്, ഇതിന്റേതല്ല. തുടർന്ന് ഇവിടെയുള്ള ഓരോ വരിയും ഒരു പാരാമീറ്ററായി ചേർക്കുക: ഇടതുവശത്ത് പേര്, വലതുവശത്ത് മൂല്യം. നിങ്ങളുടെ Zabbix സെർവറിന് ഒരു പ്രോക്സി വഴി മാത്രമേ FreeITSM-ൽ എത്താനാകൂ എങ്കിൽ ഒഴികെ http_proxy ഒഴിച്ചിടുക. ബ്രേസുകളിലെ മൂല്യങ്ങൾ Zabbix macro-കളാണ് - അവ അതേപടി വിടുക. url വരി ഓരോ ടിക്കറ്റിനും Zabbix-ലെ പ്രശ്നത്തിലേക്ക് ഒരു ലിങ്ക് നൽകുന്നു; അതിന് {$ZABBIX.URL} macro നിങ്ങളുടെ Zabbix വെബ് വിലാസത്തിലേക്ക് സജ്ജമാക്കണം (Zabbix: Administration → Macros). അതില്ലെങ്കിൽ ടിക്കറ്റുകൾക്ക് ലിങ്ക് ഉണ്ടാകില്ല.',
        'zabbix_script' => 'Media type സ്ക്രിപ്റ്റ്',
        'zabbix_copy' => 'പകർത്തുക',
        'zabbix_copied' => 'പകർത്തി.',
        'zabbix_reach_hint' => 'Zabbix അലേർട്ടുകൾ അയയ്ക്കുന്ന സ്ഥലം. ഇത് നിങ്ങളുടെ പബ്ലിക് ബേസ് URL ആയി തുടങ്ങുന്നു; Zabbix അതേ സെർവറിലോ നെറ്റ്‌വർക്കിലോ ആണെങ്കിൽ, FreeITSM-ലേക്കുള്ള അതിന്റെ വഴി വ്യത്യസ്തമായിരിക്കാം - ഈ മെഷീനിലെ Docker-ലെ Zabbix-ന്, http://host.docker.internal/ എന്നതും ബാക്കി പാത്തും. ഇവിടെ മാറ്റിയാൽ പാരാമീറ്ററുകളും ഡൗൺലോഡും അതിനൊപ്പം മാറും.',
        'zabbix_tickets' => 'ഇത് ഉയർത്തുന്ന incident-കൾ',
        'zabbix_requester' => 'ഉയർത്തിയത്',
        'zabbix_requester_hint' => 'ടിക്കറ്റുകൾ വരുന്ന അഭ്യർത്ഥിച്ചയാൾ. ഡിഫോൾട്ടിന് ഒരിക്കലും മെയിൽ സ്വീകരിക്കാനാകില്ല, അതിനാൽ അലേർട്ടിനെക്കുറിച്ച് ആർക്കും ഇമെയിൽ പോകില്ല; അക്നോളജ്മെന്റുകൾ എവിടെയെങ്കിലും അയയ്ക്കണമെങ്കിൽ ഒരു യഥാർത്ഥ മോണിറ്ററിംഗ് മെയിൽബോക്സ് ഉപയോഗിക്കുക.',
        'zabbix_requester_name' => 'അഭ്യർത്ഥിച്ചയാളുടെ പേര്',
        'zabbix_company' => 'കമ്പനി',
        'zabbix_company_hint' => 'സെർവർ CMDB-യിൽ ഇല്ലെങ്കിൽ, അല്ലെങ്കിൽ അതിന്റെ CMDB ഇനത്തിന് കമ്പനി ഇല്ലെങ്കിൽ ഇത് ഉപയോഗിക്കുന്നു. ഉള്ള ഒരു സെർവർ അതിന്റെ സ്വന്തം കമ്പനിയിലേക്ക് പോകുന്നു.',
        'zabbix_team' => 'ടീം',
        'zabbix_origin' => 'ഉറവിടം',
        'zabbix_none' => '(ഒന്നുമില്ല)',
        'zabbix_priority_map' => 'തീവ്രത → മുൻഗണന',
        'zabbix_priority_hint' => 'ഓരോ Zabbix തീവ്രതയ്ക്കും ഒരു പുതിയ incident-ന് ഏത് മുൻഗണന ലഭിക്കുന്നു.',
        'zabbix_resolve' => 'പ്രശ്നം മാറുമ്പോൾ',
        'zabbix_resolve_leave' => 'നില മാറ്റാതെ വിടുക',
        'zabbix_resolve_hint' => '"recovered" സന്ദേശം എപ്പോഴും ടിക്കറ്റിൽ ചേർക്കും. അതിന്റെ നിലയും മാറണോ എന്ന് ഇത് തീരുമാനിക്കുന്നു.',
        'zabbix_link_cmdb' => 'Zabbix ഹോസ്റ്റിന്റെ അതേ പേരുള്ള CMDB ഇനം ലിങ്ക് ചെയ്യുക',
        'zabbix_link_cmdb_hint' => 'ആദ്യം മുഴുവൻ പേര്, പിന്നെ ചെറുത് (web01.example.com-ന് web01). രണ്ട് കമ്പനികൾക്കും പൊരുത്തമുണ്ടെങ്കിൽ ഒന്നും ലിങ്ക് ചെയ്യില്ല.',
        'zabbix_saved' => 'സംരക്ഷിച്ചു.',
        'zabbix_events' => 'സമീപകാല അലേർട്ടുകൾ',
        'zabbix_events_none' => 'ഇതുവരെ ഒന്നും ലഭിച്ചിട്ടില്ല. Zabbix ഒന്ന് അയയ്ക്കുമ്പോൾ തന്നെ അലേർട്ടുകൾ ഇവിടെ ദൃശ്യമാകും.',
        'zabbix_col_when' => 'ലഭിച്ചത്',
        'zabbix_col_host' => 'ഹോസ്റ്റ്',
        'zabbix_col_problem' => 'പ്രശ്നം',
        'zabbix_col_severity' => 'തീവ്രത',
        'zabbix_col_result' => 'ഫലം',
        'zabbix_col_ticket' => 'ടിക്കറ്റ്',
        'zabbix_act_created' => 'Incident ഉയർത്തി',
        'zabbix_act_updated' => 'ടിക്കറ്റിൽ ചേർത്തു',
        'zabbix_act_resolved' => 'റിക്കവർ ചെയ്തു',
        'zabbix_act_recovery_unmatched' => 'ടിക്കറ്റില്ലാത്ത റിക്കവറി',
        'zabbix_act_error' => 'പരാജയപ്പെട്ടു',
        'zabbix_recovery' => 'റിക്കവറി',
        'zabbix_test' => 'പരീക്ഷിക്കുക',
        'zabbix_test_body' => 'ഇന്റഗ്രേഷനിലൂടെ ഒരു ടെസ്റ്റ് പ്രശ്നം അയയ്ക്കുന്നു, Zabbix-ൽ നിന്നുള്ള യഥാർത്ഥ അലേർട്ട് കൈകാര്യം ചെയ്യുന്നതുപോലെ തന്നെ: നിങ്ങളുടെ ക്രമീകരണങ്ങൾ ഉപയോഗിച്ച് ഒരു incident ഉയർത്തപ്പെടുന്നു, തുടർന്ന് അത് പരിഹരിക്കപ്പെടുന്നത് കാണാൻ അതിന്റെ റിക്കവറി അയയ്ക്കാം. ടെസ്റ്റ് incident ഒരു ടെസ്റ്റ് എന്ന തലക്കെട്ടോടെ നിലനിൽക്കും, യഥാർത്ഥമായത് എങ്ങനെയിരിക്കുമെന്ന് കാണാൻ - മറ്റേതൊരു ടിക്കറ്റും പോലെ അത് അടയ്ക്കുക.',
        'zabbix_test_limit' => 'ഇത് FreeITSM-ന്റെ പകുതി പരീക്ഷിക്കുന്നു. നിങ്ങളുടെ Zabbix സെർവറിന് FreeITSM-ൽ എത്താനാകുമോ എന്നത് മറ്റേ പകുതിയാണ്: Zabbix-ലെ media type-ലുള്ള Test ബട്ടൺ ഉപയോഗിച്ച് അത് പരീക്ഷിക്കുക.',
        'zabbix_test_send' => 'ടെസ്റ്റ് അലേർട്ട് അയയ്ക്കുക',
        'zabbix_test_recover' => 'റിക്കവറി അയയ്ക്കുക',
        'zabbix_test_raised' => 'ടെസ്റ്റ് incident {ticket} ഉയർത്തി.',
        'zabbix_test_resolved' => 'റിക്കവറി ലഭിച്ചു - {ticket} പരിഹരിച്ചു.',
        'zabbix_test_failed' => 'ടെസ്റ്റ് പരാജയപ്പെട്ടു: {error}',
        'zabbix_test_trigger' => 'FreeITSM-ൽ നിന്നുള്ള ടെസ്റ്റ് അലേർട്ട്',
        'zabbix_test_message' => 'ഇത് System → Integrations → Zabbix-ൽ നിന്ന് അയച്ച ഒരു ടെസ്റ്റ് ആണ്. ഒരു കുഴപ്പവുമില്ല.',
        'msteams_blurb' => 'സർവീസ് ഡെസ്ക് അലേർട്ടുകൾ നിങ്ങളുടെ Teams ചാനലുകളിൽ കാർഡുകളായി - അടിയന്തര ടിക്കറ്റുകൾ, SLA ലംഘനങ്ങൾ, ഓരോ ടീമിനുമുള്ള ടിക്കറ്റുകൾ - ടിക്കറ്റിലേക്ക് നേരിട്ടുള്ള ഒരു ബട്ടണോടെ.',
        'msteams_intro' => 'സർവീസ് ഡെസ്ക് അലേർട്ടുകൾ Microsoft Teams ചാനലുകളിലേക്ക് കാർഡുകളായി പോസ്റ്റ് ചെയ്യുക, ഓരോന്നിലും Open in FreeITSM ബട്ടൺ ഉണ്ടാകും. ഓരോ ചാനലും എന്തിനെക്കുറിച്ച് അറിയണമെന്ന് ടിക്ക് ചെയ്യുക: അടിയന്തര ടിക്കറ്റുകൾ, SLA മുന്നറിയിപ്പുകളും ലംഘനങ്ങളും, അതിന്റെ ടീമുകളുടെ ടിക്കറ്റുകൾ, സ്റ്റാറ്റസ് പേജ് incident-കൾ, കാത്തിരിക്കുന്ന അനുമതികൾ.',
        'msteams_not_ready' => 'ആദ്യം System → Database Verification പ്രവർത്തിപ്പിക്കുക: ഈ അലേർട്ടുകൾ സൂക്ഷിക്കുന്ന പട്ടികകൾ അത് സൃഷ്ടിക്കുന്നു.',
        'msteams_bot_h' => 'Teams ചാറ്റ് ബോട്ട്',
        'msteams_bot_body' => 'ഈ പേജ് അലേർട്ടുകൾ മാത്രമേ പോസ്റ്റ് ചെയ്യൂ. ആളുകൾക്ക് Teams-ൽ സർവീസ് ഡെസ്കുമായി ചാറ്റ് ചെയ്യാൻ - ഓരോ സംഭാഷണവും ഒരു ടിക്കറ്റ് - Tickets → Settings → Messaging-ന് കീഴിൽ Teams ബോട്ട് സെറ്റപ്പ് ചെയ്യുക.',
        'msteams_bot_count' => '{n} Teams ബോട്ട് ചാനൽ(കൾ) സെറ്റപ്പ് ചെയ്തു.',
        'msteams_bot_link' => 'Messaging ക്രമീകരണങ്ങൾ തുറക്കുക',
        'msteams_how_h' => 'ഒരു ചാനലിന്റെ webhook വിലാസം നേടുക',
        'msteams_how_body' => 'Teams-ൽ ചാനൽ തുറക്കുക, അതിന്റെ പേരിന് അടുത്തുള്ള … ക്ലിക്ക് ചെയ്യുക, തുടർന്ന് Workflows. "Post to a channel when a webhook request is received" തിരഞ്ഞെടുക്കുക, ഘട്ടങ്ങൾ പിന്തുടരുക, അവസാനം ലഭിക്കുന്ന വിലാസം പകർത്തുക. താഴെയുള്ള ഒരു ചാനലിൽ അത് പേസ്റ്റ് ചെയ്യുക. വിലാസം ഒരു പാസ്‌വേഡ് പോലെയാണ്: അത് കൈവശമുള്ള ആർക്കും ആ ചാനലിലേക്ക് പോസ്റ്റ് ചെയ്യാം, അതിനാൽ അത് എൻക്രിപ്റ്റ് ചെയ്ത് സൂക്ഷിക്കുന്നു, ഒരിക്കലും വീണ്ടും കാണിക്കില്ല.',
        'msteams_channels_h' => 'ചാനലുകൾ',
