        'msteams_alert_priority_new' => 'ഒരു പുതിയ ടിക്കറ്റ് ഈ മുൻഗണനയിലോ അതിന് മുകളിലോ ആകുമ്പോൾ',
        'msteams_alert_priority_raised' => 'ഒരു ടിക്കറ്റ് അതിലേക്ക് ഉയർത്തുമ്പോൾ',
