        'msteams_no_teams' => 'ഇതുവരെ ടീമുകളില്ല.',
        'msteams_workflows_note' => 'ടിക്ക് ചെയ്ത ഓരോ അലേർട്ടും Workflows പേജിൽ "Teams: …" എന്ന പേരുള്ള ഒരു വർക്ക്ഫ്ലോ ആണ്, അവിടെയാണ് അതിന്റെ ചരിത്രവും ഡെലിവറികളും. ഇവിടെ മാറ്റുക: അവിടെ വരുത്തുന്ന മാറ്റം ഈ ചാനൽ അടുത്ത തവണ സംരക്ഷിക്കുമ്പോൾ മാറ്റിസ്ഥാപിക്കപ്പെടും.',
        'msteams_on' => '{n} അലേർട്ട്(കൾ) ഓൺ',
        'msteams_saved' => 'സംരക്ഷിച്ചു - {n} അലേർട്ട്(കൾ) ഓൺ.',
        'msteams_test' => 'പരിശോധിക്കുക',
        'msteams_test_sent' => 'അയച്ചു ({detail}) - Teams-ലെ ചാനലിൽ നോക്കുക.',
        'msteams_test_failed' => 'Teams ഇത് സ്വീകരിച്ചില്ല: {detail}',
        'msteams_delete_confirm' => 'ഈ ചാനലും അത് ഉണ്ടാക്കിയ വർക്ക്ഫ്ലോകളും ഇല്ലാതാക്കണോ? അവയുടെ ചരിത്രം Workflows പേജിൽ നിലനിൽക്കും.',
        'msteams_needs_name' => 'ചാനലിന് ഒരു പേര് നൽകുക.',
        'threecx_blurb' => 'ഉത്തരം നൽകുന്നതിന് മുമ്പ് ആരാണ് വിളിക്കുന്നതെന്ന് കാണുക, ഓരോ കോളും വിളിച്ചയാളുടെ ടിക്കറ്റിൽ സൂക്ഷിക്കുക, ഒറ്റ ക്ലിക്കിൽ ഒരു നമ്പർ ഡയൽ ചെയ്യുക.',
        'threecx_intro' => 'ഒരു കോൾ റിംഗ് ചെയ്യുമ്പോൾ, ആ നമ്പർ ആരുടേതാണെന്ന് 3CX FreeITSM-നോട് ചോദിച്ച് വിളിച്ചയാളുടെ പേര് കാണിക്കുന്നു - അനലിസ്റ്റിനായി അവരുടെ ടിക്കറ്റും തുറക്കുന്നു. കോൾ അവസാനിക്കുമ്പോൾ, അത് എടുത്ത അനലിസ്റ്റ് എഴുതിയതായി ആ ടിക്കറ്റിൽ കുറിക്കുന്നു. ടിക്കറ്റുകളിലെയും ആളുകളുടെയും ഫോൺ നമ്പറുകളും 3CX വഴി ഡയൽ ചെയ്യാം.',
        'threecx_direction' => '3CX FreeITSM-നെ വിളിക്കുന്നു - FreeITSM ഒരിക്കലും 3CX-ലേക്ക് കണക്ട് ചെയ്യുന്നില്ല, അതിനാൽ നിങ്ങളുടെ ഫോൺ സിസ്റ്റത്തിന്റെ വിലാസമോ 3CX പാസ്‌വേഡോ ആവശ്യമില്ല. 3CX-ന് വേണ്ടതെല്ലാം താഴെയുള്ള ടെംപ്ലേറ്റിലുണ്ട്.',
        'threecx_not_ready' => 'ആദ്യം System → Database Verification പ്രവർത്തിപ്പിക്കുക: ഈ ഇന്റഗ്രേഷൻ അതിന്റെ കോൾ ലോഗ് സൂക്ഷിക്കുന്ന പട്ടിക അത് സൃഷ്ടിക്കുന്നു.',
        'threecx_connect' => '3CX കണക്ട് ചെയ്യുക',
        'threecx_connect_body' => '3CX ഒരു CRM ടെംപ്ലേറ്റ് വഴിയാണ് FreeITSM-മായി ബന്ധിപ്പിക്കുന്നത്. ഒരു ടോക്കൺ ഉണ്ടാക്കുക, ടെംപ്ലേറ്റ് ഡൗൺലോഡ് ചെയ്യുക, 3CX Admin Console-ൽ Integrations → CRM എന്നതിന് കീഴിൽ അപ്‌ലോഡ് ചെയ്യുക. താഴെയുള്ള വിലാസത്തിൽ 3CX-ന് എത്താൻ കഴിയണം.',
        'threecx_endpoint' => 'FreeITSM-ന്റെ വിലാസം, 3CX എത്തുന്ന രീതിയിൽ',
        'threecx_reach_hint' => 'ഇത് നിങ്ങളുടെ പബ്ലിക് ബേസ് URL ആയി തുടങ്ങുന്നു. 3CX പലപ്പോഴും ക്ലൗഡിലായിരിക്കും, അതിനാൽ ഇത് ഇന്റർനെറ്റിന് എത്താവുന്ന ഒരു വിലാസമായിരിക്കണം. ഇവിടെ മാറ്റിയാൽ ഡൗൺലോഡും അതിനൊപ്പം മാറും.',
