        'threecx_create_unknown' => 'FreeITSM-ൽ ആർക്കുമില്ലാത്ത നമ്പറുകൾക്കും',
        'threecx_create_hint' => 'വരുന്ന കോളുകൾക്ക് മാത്രം (എടുത്തതോ മിസ്സായതോ). കോൾ എടുത്ത അനലിസ്റ്റിനെ നിയോഗിക്കുന്നു. അജ്ഞാതനായ വിളിച്ചയാളെ "Caller" എന്നും അവരുടെ നമ്പറും ആയി രേഖപ്പെടുത്തുന്നു, ശരിയായ വ്യക്തിയുമായി ലിങ്ക് ചെയ്യാൻ തയ്യാറായി.',
        'threecx_fallback' => '3CX ഉപയോക്താവ് അനലിസ്റ്റ് അല്ലാത്തപ്പോൾ കുറിപ്പുകൾ എഴുതുന്നത്',
        'threecx_fallback_hint' => 'കോൾ എടുത്ത 3CX ഉപയോക്താവിന്റെ ഇമെയിലുമായി പൊരുത്തപ്പെടുന്ന അനലിസ്റ്റ് ആണ് കുറിപ്പ് എഴുതുന്നത്. ആരും പൊരുത്തപ്പെടാത്തപ്പോൾ - ഒരു റിസപ്ഷനിസ്റ്റ്, പങ്കിട്ട ഫോൺ - ആര് എടുത്തു എന്ന് പറഞ്ഞുകൊണ്ട് പകരം ഈ അനലിസ്റ്റ് അത് എഴുതുന്നു. ആരെയും തിരഞ്ഞെടുത്തില്ലെങ്കിൽ, ആ കോളുകൾ താഴെ പട്ടികപ്പെടുത്തുക മാത്രം ചെയ്യുന്നു.',
