        'threecx_company_hint' => 'അറിയാവുന്ന വിളിച്ചയാളുടെ ടിക്കറ്റ് അവരുടെ സ്വന്തം കമ്പനിയിൽ പോകുന്നു.',
        'threecx_team' => 'പുതിയ ടിക്കറ്റുകൾക്കുള്ള ടീം',
