        'threecx_dial_body' => 'ടിക്കറ്റുകളിലെയും Tickets → Users-ലെയും People-ലെയും ഫോൺ നമ്പറുകൾക്ക് നിങ്ങളുടെ ഫോൺ വഴി ഡയൽ ചെയ്യുന്ന ഒരു Call ബട്ടൺ ലഭിക്കുന്നു. ഇത് അനലിസ്റ്റിന്റെ സ്വന്തം കമ്പ്യൂട്ടറിൽ തുറക്കുന്നു, അവിടെ അവർ ഇതിനകം 3CX-ൽ സൈൻ ഇൻ ചെയ്തിരിക്കുന്നു, അതിനാൽ FreeITSM-ന് അവരുടെ എക്സ്റ്റൻഷൻ ഒരിക്കലും ആവശ്യമില്ല.',
        'threecx_dial' => 'ഡയൽ വിലാസം',
