        'intro' => 'ഓരോ അനലിസ്റ്റിന്റെയും ഭാഷയിൽ, FreeITSM-ന്റെ സ്വന്തം സഹായത്തിൽ നിന്ന് "എങ്ങനെ ചെയ്യാം...?" എന്ന ചോദ്യങ്ങൾക്ക് ഉത്തരം നൽകുന്ന, ഓരോ പേജിലുമുള്ള ഒരു അസിസ്റ്റന്റ്.',
        'no_ai_title' => 'ഹെൽപ്പ് അസിസ്റ്റന്റ് AI ഇല്ലാതെയും പ്രവർത്തിക്കും.',
        'no_ai_body' => 'ഒന്നും സജ്ജമാക്കിയില്ലെങ്കിൽ ഇത് എല്ലാ സഹായ പേജുകളിലും തിരഞ്ഞ് നിങ്ങളുടെ അനലിസ്റ്റുകളെ ശരിയായ സെക്ഷനിലേക്ക് നേരിട്ട് എത്തിക്കും - സൗജന്യം, തൽക്ഷണം, നിങ്ങളുടെ സെർവറിൽ നിന്ന് ഒന്നും പുറത്തുപോകില്ല.',
