        'level_meaning' => 'ഹെൽപ്പ് തിരയൽ, അർത്ഥം അനുസരിച്ച് പൊരുത്തപ്പെടുത്തൽ - ചാറ്റ് AI സജ്ജമാക്കിയിട്ടില്ല',
