        'named_hint' => 'സഹായത്തിന് ഉത്തരം നൽകാൻ കഴിയാത്ത ഒരു ചോദ്യത്തോടൊപ്പം ആ അനലിസ്റ്റിന്റെ പേര് സൂക്ഷിക്കാൻ ആരാണ് ചോദിച്ചതെന്ന് രേഖപ്പെടുത്തുക എന്നത് ടിക്ക് ചെയ്യുക - അവരുടെ വിൻഡോയിൽ അത് അറിയിക്കും. ടിക്ക് മാറ്റിയാലും ചോദ്യം പേരില്ലാതെ സൂക്ഷിക്കും.',
        'unanswered_heading' => 'ഉത്തരം കിട്ടാത്ത ചോദ്യങ്ങൾ',
        'unanswered_intro' => 'ഹെൽപ്പ് അസിസ്റ്റന്റിന് ഉത്തരം നൽകാൻ കഴിയാത്ത ചോദ്യങ്ങൾ - ഒന്നും കണ്ടെത്തിയില്ല, അല്ലെങ്കിൽ ദുർബലമായ പൊരുത്തങ്ങൾ മാത്രം - ആളുകളുടെ സ്വന്തം വാക്കുകളിൽ: എഴുതേണ്ട സഹായത്തിന്റെ ഏറ്റവും നല്ല പട്ടിക. അഡ്മിനിസ്ട്രേറ്റർമാർക്ക് ഒരു ബെൽ അറിയിപ്പ് ലഭിക്കും; ചോദിച്ച വ്യക്തിക്ക് ഒരിക്കലും ലഭിക്കില്ല.',
