        'vectors_intro' => 'അസിസ്റ്റന്റിന് ഒരു എംബെഡിംഗ് മോഡൽ നൽകിയാൽ, ഉപയോഗിച്ച വാക്കുകൾ മാത്രമല്ല, ചോദ്യങ്ങളുടെ അർത്ഥം അനുസരിച്ച് അത് പൊരുത്തപ്പെടുത്തും - അതിനാൽ "എന്റെ ബോസിന് ആഴ്ചതോറും ഒരു PDF വേണം" എന്നത് Report packs കണ്ടെത്തും. അളന്ന പരീക്ഷണ ചോദ്യങ്ങളിൽ, അയഞ്ഞ വാക്കുകളിലുള്ളവയിൽ 6-ൽ 2 എണ്ണത്തിന് ഉത്തരം കിട്ടിയിരുന്നത് 6-ൽ 6 ആയി.',
        'vectors_cost' => 'വെക്ടറുകൾ നിർമ്മിക്കാൻ OpenAI-യിൽ ഏകദേശം ഒരു പെന്നി ചെലവാകും, അതിനുശേഷം ഓരോ ചോദ്യത്തിനും അതിന്റെ ചെറിയൊരു അംശം മാത്രം. ഇതിന് സ്വന്തം കീ ഉള്ളതിനാൽ ചെലവ് പ്രത്യേകം കാണിക്കും.',
        'vectors_privacy' => 'ഓരോ ചോദ്യവും വെക്ടറായി മാറ്റാൻ നിങ്ങൾ തിരഞ്ഞെടുക്കുന്ന ദാതാവിന് അയയ്ക്കുന്നു. എല്ലാം നിങ്ങളുടെ നെറ്റ്‌വർക്കിൽ തന്നെ നിലനിർത്താൻ സ്വന്തം മോഡൽ സെർവർ തിരഞ്ഞെടുക്കുക.',
        'vectors_enable' => 'അർത്ഥം അനുസരിച്ച് ചോദ്യങ്ങൾ പൊരുത്തപ്പെടുത്തുക',
