        'status_off' => 'ഓഫ് - അസിസ്റ്റന്റ് വാക്കുകൾ അനുസരിച്ച് തിരയുന്നു.',
        'status_in_use' => 'ഉപയോഗത്തിൽ: {model} - {count} സെക്ഷനുകൾ അർത്ഥം അനുസരിച്ച് പൊരുത്തപ്പെടുത്തി.',
        'status_first' => '{model}-നുള്ള വെക്ടറുകൾ ഇതുവരെ നിർമ്മിച്ചിട്ടില്ല - റീബിൽഡ് അമർത്തുക. അതുവരെ അസിസ്റ്റന്റ് വാക്കുകൾ അനുസരിച്ച് തിരയും.',
        'warn_switch' => 'നിങ്ങളുടെ ഹെൽപ്പ് വെക്ടറുകൾ {active} ഉപയോഗിച്ചാണ് നിർമ്മിച്ചത്, നിങ്ങൾ {chosen} തിരഞ്ഞെടുത്തിരിക്കുന്നു. വ്യത്യസ്ത മോഡലുകളിലെ വെക്ടറുകൾ താരതമ്യം ചെയ്യാൻ കഴിയില്ല, അതിനാൽ ഈ മോഡലിനായി സഹായത്തിന് പുതിയ വെക്ടറുകൾ വേണം - ഏകദേശം {count} സെക്ഷനുകൾ. അവ നിർമ്മിക്കുന്നതുവരെ അസിസ്റ്റന്റ് {active} ഉപയോഗിക്കുന്നത് തുടരും.',
        'warn_stale' => '{n} സെക്ഷനുകൾ അവയുടെ വെക്ടറുകൾ നിർമ്മിച്ചതിന് ശേഷം മാറിയിട്ടുണ്ട് - പുതുക്കാൻ റീബിൽഡ് ചെയ്യുക.',
        'use_shipped' => 'റെഡിമെയ്ഡ് വെക്ടറുകൾ ഉപയോഗിക്കുക',
        'shipped_note' => 'ഈ മോഡലിന് ഈ റിലീസിനൊപ്പം റെഡിമെയ്ഡ് വെക്ടറുകൾ ഉണ്ട്, അതിനാൽ ഇതിലേക്ക് മാറുന്നത് തൽക്ഷണവും ചെലവില്ലാത്തതുമാണ്.',
        'switch_heading' => 'ഓണാക്കുക',
        'enable_label' => 'ഹെൽപ്പ് അസിസ്റ്റന്റ് ഓണാക്കുക',
        'enable_hint' => 'ഓണാക്കുന്നതുവരെ ഓഫ് ആയിരിക്കും. തുടർന്ന് ആർക്കൊക്കെ ഇത് ലഭിക്കണമെന്ന് താഴെ ടിക്ക് ചെയ്യുക - നിങ്ങൾ തിരഞ്ഞെടുക്കുന്നതുവരെ ആർക്കും ഇത് ഉണ്ടാകില്ല.',
        'who_heading' => 'ആർക്കൊക്കെ ഉണ്ട്',
        'who_hint' => 'ഇവിടെ ടിക്ക് ചെയ്യുന്ന ഓരോ അനലിസ്റ്റിനും എല്ലാ പേജിലും ഹെഡറിൽ ഒരു സഹായ ഐക്കൺ ലഭിക്കും.',
