        'index_heading' => 'ഹെൽപ്പ് ഇൻഡക്സ്',
        'index_hint' => 'ഓരോ സഹായ പേജും ഒരിക്കൽ വായിച്ച് തിരയാൻ തയ്യാറാക്കി സൂക്ഷിക്കുന്നു - ഇംഗ്ലീഷിലും നിങ്ങളുടെ അനലിസ്റ്റുകൾ ഉപയോഗിക്കുന്ന ഭാഷകളിലും. അസിസ്റ്റന്റ് ഓണാക്കി ആദ്യമായി സേവ് ചെയ്യുമ്പോൾ ഇത് നിർമ്മിക്കപ്പെടും; ഒരു അപ്ഗ്രേഡ് സഹായത്തിൽ മാറ്റം വരുത്തിയാൽ ഇത് റീബിൽഡ് ചെയ്യുക.',
