    'status_portal' => [
        'heading' => 'പോർട്ടലിലെ സേവന നില',
        'intro' => 'എൻഡ് യൂസർമാർ ഇതിനകം സെൽഫ്-സർവീസ് പോർട്ടലിൽ ഏതൊക്കെ സേവനങ്ങൾ ശരിയായി പ്രവർത്തിക്കുന്നു എന്ന് കാണുന്നുണ്ട്. ഒരു തടസ്സത്തിന് പിന്നിലെ <strong>സംഭവങ്ങളും</strong>, നിങ്ങളുടെ ടീം എക്സ്റ്റേണൽ എന്ന് അടയാളപ്പെടുത്തിയ അപ്ഡേറ്റുകളും അവർ കാണുമോ എന്ന് ഇത് തീരുമാനിക്കുന്നു.',
        'warning' => '<strong>ഇത് ഓണാക്കുന്നതിന് മുൻപ് വായിക്കുക.</strong> സംഭവങ്ങളുടെ തലക്കെട്ടുകൾ എഴുതിയിരിക്കുന്നത് നിങ്ങളുടെ ടീമിന് വേണ്ടിയാണ്, ഉപഭോക്താക്കൾക്ക് വേണ്ടിയല്ല &mdash; എൻഡ് യൂസർമാർ അവ വായിക്കാൻ തുടങ്ങുന്നതിന് മുൻപ് നിങ്ങളുടേത് എന്താണ് പറയുന്നതെന്ന് പരിശോധിക്കുക. വ്യക്തമായി <strong>എക്സ്റ്റേണൽ</strong> എന്ന് അടയാളപ്പെടുത്തിയ അപ്ഡേറ്റുകൾ മാത്രമേ എപ്പോഴും കാണിക്കൂ; ഈ ഫീച്ചർ വരുന്നതിന് മുൻപ് എഴുതിയതെല്ലാം ഇന്റേണൽ ആണ്, അതായി തുടരും.',
        'panel_heading' => 'പോർട്ടൽ കാണിക്കുന്നത്',
        'enable_label' => 'സെൽഫ്-സർവീസ് പോർട്ടലിൽ സംഭവങ്ങളും അവയുടെ എക്സ്റ്റേണൽ അപ്ഡേറ്റുകളും കാണിക്കുക',
