        'intro' => 'Files റീസൈക്കിൾ ബിൻ, ഒരു ഫോൾഡർ ഇല്ലാതാക്കിയ വ്യക്തിക്ക് അതിലെ എല്ലാം സ്വയം ഇല്ലാതാക്കാൻ കഴിയുമായിരുന്നെങ്കിൽ മാത്രമേ നിലനിർത്തൽ കാലയളവിന് ശേഷം അത് ശാശ്വതമായി ഇല്ലാതാക്കൂ. ഈ ഫോൾഡറുകളിൽ ആ വ്യക്തിക്ക് മാറ്റാൻ കഴിയാത്ത ഫോൾഡറുകളുണ്ട്, അതിനാൽ എന്ത് ചെയ്യണമെന്ന് ആരെങ്കിലും തീരുമാനിക്കുന്നതുവരെ - അവയുടെ തീയതി കഴിഞ്ഞും - അവ സൂക്ഷിക്കുന്നു. ഇവിടെ ഒന്നും സ്വയമേവ ഇല്ലാതാക്കില്ല.',
