        'intro' => 'സ്വതന്ത്രമായി പ്രവർത്തിക്കുന്ന ഡയഗ്നോസ്റ്റിക്കുകളുടെ ലൈബ്രറി. എന്തെങ്കിലും പ്രവർത്തിക്കാതെ വരുമ്പോൾ, ബന്ധപ്പെട്ട ടൂൾ പ്രവർത്തിപ്പിച്ച് ഔട്ട്പുട്ട് സപ്പോർട്ടിന് തിരികെ അയക്കുക — ആവർത്തിച്ചുള്ള ആശയവിനിമയമില്ലാതെ കാരണം കണ്ടെത്താൻ ആവശ്യമായ എൻവയോൺമെന്റും റൺടൈം വിവരങ്ങളും ഓരോ ഡയഗ്നോസ്റ്റിക്കും ശേഖരിക്കുന്നു.',
