        'format_follow_default' => 'സിസ്റ്റം സ്ഥിരസ്ഥിതി ഉപയോഗിക്കുക ({example})',
        'format_saved' => 'ഫോർമാറ്റ് സേവ് ചെയ്തു',
        'sidebar_heading' => 'സൈഡ്ബാർ',
        'sidebar_desc' => 'വാഫിൾ മെനു തുറക്കുന്നതിന് പകരം, നിങ്ങളുടെ മൊഡ്യൂളുകൾ ഓരോ സ്ക്രീനിന്റെയും ഇടതുവശത്ത് ഒരു ക്ലിക്ക് അകലെ നിലനിർത്തുക. വാഫിൾ എന്തായാലും അവിടെത്തന്നെ ഉണ്ടാകും. ഫോണിൽ കാണിക്കില്ല.',
        'sidebar_label' => 'സൈഡ്ബാർ കാണിക്കുക',
        'sidebar_pick' => 'അതിൽ വേണ്ട മൊഡ്യൂളുകൾ ടിക്ക് ചെയ്യുക. മുകളിലുള്ള നിങ്ങളുടെ മൊഡ്യൂൾ ക്രമത്തിൽ അവ കാണും.',
        'sidebar_on' => 'സൈഡ്ബാർ ഓണാണ് - നിങ്ങൾ തുറക്കുന്ന അടുത്ത പേജിൽ ഇത് കാണും',
        'sidebar_off' => 'സൈഡ്ബാർ ഓഫാണ്',
        'sidebar_saved' => 'സൈഡ്ബാർ സംരക്ഷിച്ചു',
        'sidebar_names' => 'മൊഡ്യൂൾ പേരുകൾ',
        'sidebar_names_icons' => 'ഐക്കണുകൾ മാത്രം - പേരിനായി ഒന്നിൽ പോയിന്റ് ചെയ്യുക',
        'sidebar_names_hover' => 'സൈഡ്ബാറിൽ പോയിന്റ് ചെയ്യുമ്പോൾ പേരുകളോടെ തുറക്കുക',
        'sidebar_names_pinned' => 'എപ്പോഴും പേരുകളോടെ തുറന്നിരിക്കുക',
        'sidebar_waffle' => 'വാഫിൾ ബട്ടൺ',
        'sidebar_waffle_show' => 'കാണിക്കുക',
        'sidebar_waffle_hide' => 'മറയ്ക്കുക - Recent സൈഡ്ബാറിലുണ്ട്, ഫോണിൽ ഇപ്പോഴും കാണിക്കും',
        'modorder_heading' => 'മൊഡ്യൂൾ ക്രമം',
        'modorder_desc' => 'നിങ്ങളുടെ വാഫിൾ മെനുവിലും ഹോം പേജിലും Ctrl+K "Go to" ലിസ്റ്റിലും മൊഡ്യൂളുകളുടെ ക്രമം. ഒരു മൊഡ്യൂളിനെ അതിന്റെ ഹാൻഡിൽ ഉപയോഗിച്ച് വലിച്ചിടുക, അമ്പടയാളങ്ങൾ ഉപയോഗിക്കുക, അല്ലെങ്കിൽ ഒന്ന് തിരഞ്ഞെടുത്ത് Alt-ഉം മുകളിലേക്കോ താഴേക്കോ ഉള്ള അമ്പടയാളവും അമർത്തുക. ഈ ക്രമം നിങ്ങൾ മാത്രമേ കാണൂ.',
        'modorder_note' => 'മാറ്റുന്നതിനൊപ്പം സംരക്ഷിക്കപ്പെടും, നിങ്ങൾ തുറക്കുന്ന അടുത്ത പേജ് മുതൽ ഉപയോഗിക്കും. പിന്നീടുള്ള അപ്ഡേറ്റിൽ ചേർക്കുന്ന മൊഡ്യൂൾ സ്വയം ലിസ്റ്റിൽ ചേരും.',
