        'scope_note' => 'സമയങ്ങളെക്കുറിച്ച് തന്നെ ഒന്നും ഇല്ല. ഒരു സമയം ഏത് സമയമേഖലയിൽ കാണിക്കുന്നു എന്നത് ഓരോ അനലിസ്റ്റിനും Preferences-ൽ പ്രത്യേകം സെറ്റ് ചെയ്യുന്നു - തീയതികൾ ഏത് വിധേനയും മാറ്റമില്ലാതെ സൂക്ഷിക്കുന്നു, അതിനാൽ service level targets, reports, exports എന്നിവയെ ഇത് ബാധിക്കില്ല.',
        'saved' => 'തീയതിയും സമയവും ഫോർമാറ്റുകൾ സേവ് ചെയ്തു',
        'error' => 'സേവ് ചെയ്യാൻ കഴിഞ്ഞില്ല: {error}',
