    'currencies' => [
        'title' => 'Currencies',
        'subtitle' => 'ലോകത്ത് ഉപയോഗത്തിലുള്ള എല്ലാ കറൻസിയും FreeITSM പണം രേഖപ്പെടുത്തുന്ന എല്ലായിടത്തും ലഭ്യമാണ്. ഏതൊക്കെ ആദ്യം വരണം, പുതിയ റെക്കോർഡുകൾ ഏത് കറൻസിയിൽ തുടങ്ങണം, തുകകൾ എങ്ങനെ എഴുതണം എന്ന് തിരഞ്ഞെടുക്കുക. ഏത് അനലിസ്റ്റിനും Preferences-ൽ തങ്ങൾക്കായി മറ്റൊരു ഫോർമാറ്റ് തിരഞ്ഞെടുക്കാം.',
        'fav_heading' => 'പ്രിയപ്പെട്ടവ',
        'fav_desc' => 'ഓരോ കറൻസി ലിസ്റ്റിന്റെയും മുകളിൽ കാണിക്കുന്ന പരമാവധി {max} കറൻസികൾ. Default എന്ന് അടയാളപ്പെടുത്തിയതിലാണ് പുതിയ കരാർ, ലൈസൻസ്, ഡൊമെയ്ൻ, ലീസ് അല്ലെങ്കിൽ പ്രോജക്റ്റ് തുടങ്ങുന്നത്.',
        'fav_default' => 'സ്ഥിരസ്ഥിതി',
        'fav_remove' => '{code} നീക്കം ചെയ്യുക',
        'fav_add' => 'ചേർക്കുക',
        'fav_full' => 'പ്രിയപ്പെട്ടവയുടെ പരമാവധി എണ്ണം ഇതാണ്. മറ്റൊന്ന് ചേർക്കാൻ ഒന്ന് നീക്കം ചെയ്യുക.',
        'fav_existing' => 'സ്ഥിരസ്ഥിതി മാറ്റുന്നത് ഇതിനകം ഒരു കറൻസിയുള്ള റെക്കോർഡിനെ ഒരിക്കലും മാറ്റില്ല.',
        'format_heading' => 'തുകകൾ എങ്ങനെ എഴുതുന്നു',
        'format_desc' => 'താഴെയുള്ള ഒരു ഒഴിവാക്കൽ മറിച്ച് പറയുന്നില്ലെങ്കിൽ, എല്ലാ കറൻസിക്കുമുള്ള ഫോർമാറ്റ്. ദശാംശ സ്ഥാനങ്ങൾ "As the currency" എന്നത് കറൻസിയെത്തന്നെ പിന്തുടരുന്നു: യെന്നിന് ഒന്നുമില്ല, പൗണ്ടിന് രണ്ട്, കുവൈത്തി ദിനാറിന് മൂന്ന്.',
        'preview_label' => 'നിങ്ങളുടെ പ്രിയപ്പെട്ടവ ഇങ്ങനെ കാണും',
        'exc_heading' => 'പ്രത്യേക കറൻസികൾക്കുള്ള ഒഴിവാക്കലുകൾ',
        'exc_desc' => 'ഒരു കറൻസിക്ക് മാത്രം വ്യത്യസ്ത ഫോർമാറ്റ് - ഉദാഹരണത്തിന് ബാക്കിയെല്ലാം മുകളിലെ പോലെ തുടരുമ്പോൾ രൂപിയ ഇന്തോനേഷ്യൻ രീതിയിൽ, Rp 1.500.000 എന്ന് എഴുതുന്നത്.',
        'exc_none' => 'ഒഴിവാക്കലുകളില്ല. എല്ലാ കറൻസിയും മുകളിലെ ഫോർമാറ്റ് ഉപയോഗിക്കുന്നു.',
        'exc_add' => 'ചേർക്കുക',
        'exc_remove' => 'നീക്കം ചെയ്യുക',
        'unknown_heading' => 'നിങ്ങളുടെ റെക്കോർഡുകളിലെ തിരിച്ചറിയാത്ത കോഡുകൾ',
        'unknown_desc' => 'കറൻസികൾ ഒരു ലിസ്റ്റ് ആകുന്നതിന് മുമ്പ് ടൈപ്പ് ചെയ്തതാണിവ. അവ ഇപ്പോഴും ഉള്ളതുപോലെ കാണിക്കുന്നു, പക്ഷേ ലിസ്റ്റിൽ നിന്ന് ഒരു കറൻസി തിരഞ്ഞെടുക്കുന്നതുവരെ റെക്കോർഡ് സേവ് ചെയ്യാനാവില്ല.',
        'unknown_row' => '{code} - {where}-ൽ {count}',
        'saved' => 'കറൻസികൾ സംരക്ഷിച്ചു',
        'error' => 'സംരക്ഷിക്കാനായില്ല: {error}',
        'save_failed' => 'കറൻസികൾ സംരക്ഷിക്കാനായില്ല',
