        'cb_enabled' => 'പ്രവർത്തനക്ഷമം',
        'cb_enabled_desc' => 'ഈ provider-ന്റെ ബട്ടൺ ലോഗിൻ പേജിൽ കാണിക്കുക',
        'cb_enabled_desc_carddav' => 'ഈ address book ഉപയോഗിക്കുക. ക്രമീകരണങ്ങൾ ഇല്ലാതാക്കാതെ ഇതിൽ നിന്ന് contacts വായിക്കുന്നത് നിർത്താൻ ഇത് ഓഫ് ചെയ്യുക.',
        'cb_autocreate' => 'ആദ്യ ലോഗിനിൽ ഉപയോക്താക്കളെ സ്വയമേവ സൃഷ്ടിക്കുക (JIT)',
        'cb_autocreate_desc' => 'ഈ provider വഴി ആരെങ്കിലും ആദ്യമായി സൈൻ ഇൻ ചെയ്യുമ്പോൾ ഒരു അനലിസ്റ്റിനെ സ്വയമേവ സൃഷ്ടിക്കുക. മുൻകൂട്ടി സൃഷ്ടിച്ച ഉപയോക്താക്കൾക്ക് മാത്രം പ്രവേശിക്കാവുന്ന, കർശനമായി നിയന്ത്രിച്ച pilots-ന് ഇത് ഓഫ് ആയി വിടുക.',
        'cb_autocreate_users' => 'ആദ്യ ലോഗിനിൽ പോർട്ടൽ അഭ്യർത്ഥകരെ സ്വയം സൃഷ്ടിക്കുക (JIT)',
        'cb_autocreate_users_desc' => 'ഒരു എൻഡ് യൂസർ ഈ പ്രൊവൈഡർ വഴി ആദ്യമായി സൈൻ ഇൻ ചെയ്യുമ്പോൾ സെൽഫ്-സർവീസ് പോർട്ടൽ അക്കൗണ്ട് സ്വയമേവ സൃഷ്ടിക്കുക.',
        'cb_autocreate_analysts' => 'ആദ്യ ലോഗിനിൽ IT അനലിസ്റ്റുകളെ സ്വയം സൃഷ്ടിക്കുക (JIT)',
        'cb_autocreate_analysts_desc' => 'അനലിസ്റ്റ് ലോഗിൻ സ്ക്രീനിലെ ആദ്യ സൈൻ-ഇനുകൾക്ക് അനലിസ്റ്റ് അക്കൗണ്ടുകൾ സൃഷ്ടിക്കാൻ അനുവദിക്കുക. അനലിസ്റ്റുകളെ കൈകൊണ്ട് സൃഷ്ടിക്കണമെങ്കിൽ ഇത് പ്രവർത്തനരഹിതമാക്കി വയ്ക്കുക.',
        'field_fallback_mode' => 'അനലിസ്റ്റ് അല്ലാത്തവരുടെ സൈൻ-ഇൻ നടപടി',
        'field_fallback_mode_hint' => 'IT അനലിസ്റ്റ് അക്കൗണ്ട് ഇല്ലാത്ത ഒരാൾ അനലിസ്റ്റ് ലോഗിൻ സ്ക്രീനിൽ സൈൻ ഇൻ ചെയ്യുമ്പോൾ എടുക്കുന്ന നടപടി.',
        'fallback_mode_confirm' => 'സെൽഫ്-സർവീസ് പോർട്ടലിലേക്ക് മാറുന്നതിന് മുമ്പ് മുന്നറിയിപ്പ് നൽകി സ്ഥിരീകരിക്കുക',
        'fallback_mode_redirect' => 'സെൽഫ്-സർവീസ് പോർട്ടലിലേക്ക് സ്വയം മാറുക',
        'fallback_mode_block' => 'ആക്സസ് നിരസിച്ച പിശകോടെ സൈൻ-ഇൻ തടയുക',
        'cb_verified' => 'ഒരു verified-email claim ആവശ്യപ്പെടുക',
        'cb_verified_desc' => 'Provider {claim} അയയ്ക്കാത്തപക്ഷം സൈൻ-ഇൻ നിരസിക്കുക. claim തീർത്തും ഒഴിവാക്കുന്ന providers-ന് (ഉദാ. Okta-യുടെ org server) ഇത് ഓഫ് ആയി വിടുക. ഈ ക്രമീകരണം എന്തായാലും വ്യക്തമായ {claim_false} എപ്പോഴും നിരസിക്കപ്പെടും. ഉപയോക്താക്കൾക്ക് സ്ഥിരീകരിക്കാത്ത വിലാസങ്ങൾ ഉപയോഗിച്ച് സ്വയം രജിസ്റ്റർ ചെയ്യാവുന്ന IdPs-ന് മാത്രം ഇത് ഓണാക്കുക.',
        'field_profile_sync_mode' => 'പ്രൊഫൈൽ ആട്രിബ്യൂട്ട് സിങ്ക്',
        'field_profile_sync_mode_hint' => 'സൈൻ-ഇൻ സമയത്ത് IdP ക്ലെയിമുകളിൽ നിന്ന് ഉപയോക്തൃ പ്രൊഫൈൽ ആട്രിബ്യൂട്ടുകൾ (പേര്, തലക്കെട്ട്, വകുപ്പ്, ഓഫീസ്, ഫോൺ) എങ്ങനെ അപ്ഡേറ്റ് ചെയ്യുന്നു.',
        'profile_sync_always' => 'സൈൻ-ഇനിൽ എപ്പോഴും IdP-യിൽ നിന്ന് സിങ്ക് ചെയ്യുക',
        'profile_sync_initial' => 'അക്കൗണ്ട് സൃഷ്ടിക്കുമ്പോൾ സിങ്ക് ചെയ്യുക, പിന്നീട് ലോക്കൽ എഡിറ്റുകൾ അനുവദിക്കുക',
        'profile_sync_never' => 'ആട്രിബ്യൂട്ടുകൾ ഒരിക്കലും സിങ്ക് ചെയ്യരുത് (പ്രൊഫൈൽ ലോക്കലായി മാനേജ് ചെയ്യുക)',
        'field_default_modules' => 'സ്വയം സൃഷ്ടിച്ച അനലിസ്റ്റുകൾക്കുള്ള സ്ഥിര മൊഡ്യൂൾ ആക്സസ്',
        'field_jit_company' => 'സ്വയം സൃഷ്ടിച്ച അനലിസ്റ്റുകൾക്കുള്ള കമ്പനി ആക്സസ്',
        'field_jit_company_hint' => 'ഈ പ്രൊവൈഡർ സൃഷ്ടിച്ച അനലിസ്റ്റിന് ഏതൊക്കെ കമ്പനികൾ കാണാം. അക്കൗണ്ട് സൃഷ്ടിക്കുമ്പോൾ മാത്രമേ ഇത് ബാധകമാകൂ; പിന്നീട് System → Analysts-ൽ മാറ്റുക.',
        'jit_company_all' => 'എല്ലാ കമ്പനികളും (മുമ്പത്തെപ്പോലെ)',
        'jit_company_provider' => 'ഈ പ്രൊവൈഡറിന്റെ കമ്പനി മാത്രം (ഗ്ലോബൽ പ്രൊവൈഡറിന് Default കമ്പനി)',
        'jit_company_none' => 'ഒരു അഡ്മിനിസ്ട്രേറ്റർ നൽകുന്നതുവരെ ഒന്നുമില്ല',
        'tab_groups' => 'ഗ്രൂപ്പുകളും ടീമുകളും',
        'tab_portal' => 'പോർട്ടലും കമ്പനിയും',
        'claims_intro' => 'ഓപ്ഷണൽ. ആർക്ക് അനലിസ്റ്റ് ആകാം, ആരാണ് അഡ്മിനിസ്ട്രേറ്റർ, ആളുകൾ ഏതൊക്കെ ടീമുകളിലാണ് എന്ന് തീരുമാനിക്കാൻ നിങ്ങളുടെ ഐഡന്റിറ്റി പ്രൊവൈഡർ അയയ്ക്കുന്ന ഗ്രൂപ്പുകൾ ഉപയോഗിക്കുക. ഓരോ സൈൻ-ഇനിലും വീണ്ടും പരിശോധിക്കുന്നതിനാൽ ആക്സസ് ഐഡന്റിറ്റി പ്രൊവൈഡറെ പിന്തുടരും. ഒരു ടീമിന് എന്തു ചെയ്യാമെന്നത് System → Teams-ൽ സജ്ജമാക്കുന്നു.',
        'field_group_claim' => 'ഗ്രൂപ്പുകൾ എവിടെ നിന്ന് വരുന്നു',
        'field_group_claim_hint' => 'ഗ്രൂപ്പുകൾ പട്ടികപ്പെടുത്തുന്ന സൈൻ-ഇനിലെ ഭാഗം. മിക്ക പ്രൊവൈഡർമാരും ഇതിനെ groups എന്ന് വിളിക്കുന്നു; Keycloak realm_access.roles ഉപയോഗിക്കുന്നു. ഇത് അയയ്ക്കാൻ നിങ്ങളുടെ പ്രൊവൈഡർ സജ്ജമാക്കേണ്ടി വന്നേക്കാം - സഹായം കാണുക.',
        'claims_guide' => 'ഘട്ടം ഘട്ടമായുള്ള സെറ്റപ്പ് ഗൈഡ്',
        'claims_guide_hint' => 'Microsoft Entra, Okta, Keycloak എന്നിവയ്ക്കുള്ള ചെക്ക്‌ലിസ്റ്റ് സഹിതം. പുതിയ ടാബിൽ തുറക്കും.',
        'claims_off' => 'ഉപയോഗിക്കുന്നില്ല',
        'claims_other' => 'മറ്റെന്തെങ്കിലും…',
        'claims_other_ph' => 'നിങ്ങളുടെ പ്രൊവൈഡർ ഉപയോഗിക്കുന്ന പേര്',
        'group_pick_ph' => 'ഒരു ഗ്രൂപ്പ് തിരഞ്ഞെടുക്കുക അല്ലെങ്കിൽ ടൈപ്പ് ചെയ്യുക',
        'group_none' => '- ഒന്നുമില്ല -',
        'group_type' => 'ഒരു ഗ്രൂപ്പ് ടൈപ്പ് ചെയ്യുക…',
        'group_type_ph' => 'നിങ്ങളുടെ പ്രൊവൈഡർ അയയ്ക്കുന്ന അതേ രൂപത്തിൽ ഗ്രൂപ്പ്',
        'group_unseen_tag' => 'ഒരു സൈൻ-ഇനിലും ഇതുവരെ കണ്ടിട്ടില്ല',
        'group_name_ph' => 'ഒരു പേര് നൽകുക, ഉദാ. IT staff',
        'field_groups_seen' => 'കണ്ട ഗ്രൂപ്പുകൾ',
        'field_groups_seen_hint' => 'ഈ പ്രൊവൈഡർ ഒരു സൈൻ-ഇനിൽ അയച്ച എല്ലാ ഗ്രൂപ്പുകളും. Microsoft പോലുള്ള ചില പ്രൊവൈഡർമാർ പേരുകൾക്ക് പകരം കോഡുകളാണ് അയയ്ക്കുന്നത് - ഇവിടെ ഓരോന്നിനും ഒരു പേര് നൽകുക, താഴെയുള്ള ഡ്രോപ്പ്ഡൗണുകളിൽ ആ പേര് കാണിക്കും. കോഡ് നിങ്ങളുടെ പ്രൊവൈഡറിൽ ഗ്രൂപ്പിന്റെ പേരിനടുത്ത് കാണാം (Microsoft Entra-യിൽ: Groups, ഗ്രൂപ്പ്, Object ID).',
        'col_code' => 'കോഡ്',
        'col_group_name' => 'പേര്',
        'col_last_seen' => 'അവസാനം കണ്ടത്',
        'group_not_seen' => 'ഈ ഗ്രൂപ്പ് ഉപയോഗിച്ച് ഇതുവരെ ആരും സൈൻ ഇൻ ചെയ്തിട്ടില്ല - നിങ്ങളുടെ പ്രൊവൈഡർ അയയ്ക്കുന്ന അതേ അക്ഷരവിന്യാസത്തിലാണോ എന്ന് പരിശോധിക്കുക.',
        'field_claim_analyst_group' => 'അനലിസ്റ്റ് ഗ്രൂപ്പ്',
        'field_claim_analyst_group_hint' => 'ഈ ഗ്രൂപ്പിലുള്ളവർക്ക് മാത്രമേ അനലിസ്റ്റായി സൈൻ ഇൻ ചെയ്യാനാകൂ, അവരെ മാത്രമേ സ്വയം സൃഷ്ടിക്കൂ. ഗ്രൂപ്പ് വിടുന്നയാളെ അടുത്ത സൈൻ-ഇനിൽ നിരസിക്കും. ഈ പ്രൊവൈഡർ സൈൻ ഇൻ ചെയ്യിക്കുന്ന ആർക്കും ഇപ്പോഴത്തെപ്പോലെ അനലിസ്റ്റ് ആകാൻ ഇത് ഒഴിച്ചിടുക.',
        'field_claim_admin_group' => 'അഡ്മിനിസ്ട്രേറ്റർ ഗ്രൂപ്പ്',
        'field_claim_admin_group_hint' => 'ഈ ഗ്രൂപ്പിലുള്ളവർ അഡ്മിനിസ്ട്രേറ്റർമാരാണ്; അല്ലാത്തവർ അല്ല. അഡ്മിനിസ്ട്രേറ്റർമാരെ കൈകൊണ്ട് മാനേജ് ചെയ്യാൻ ഇത് ഒഴിച്ചിടുക. അവസാനത്തെ അഡ്മിനിസ്ട്രേറ്ററെ ഒരിക്കലും നീക്കം ചെയ്യില്ല.',
        'field_group_teams' => 'ടീമുകൾ',
        'field_group_teams_hint' => 'ഓരോ സൈൻ-ഇനിലും, ആളുകളെ അവരുടെ ഗ്രൂപ്പുകൾ ചൂണ്ടുന്ന ടീമുകളിൽ ചേർക്കുകയും, ഗ്രൂപ്പ് വിടുമ്പോൾ ഈ ടീമുകളിൽ നിന്ന് നീക്കുകയും ചെയ്യും. ഇവിടെ പട്ടികപ്പെടുത്താത്ത ടീമുകൾ ഒരിക്കലും മാറ്റില്ല. ഈ പ്രൊവൈഡർ സൃഷ്ടിക്കുന്ന അനലിസ്റ്റുകൾക്ക് അവരുടെ മൊഡ്യൂളുകൾ ഈ ടീമുകളിൽ നിന്ന് ലഭിക്കും.',
        'col_group' => 'ഗ്രൂപ്പ്',
        'col_team' => 'ടീം',
        'map_add' => 'ചേർക്കുക',
        'map_remove' => 'നീക്കം ചെയ്യുക',
        'choose_team' => 'ഒരു ടീം തിരഞ്ഞെടുക്കുക',
        'inactive' => 'നിഷ്ക്രിയം',
        'no_teams' => 'ഇതുവരെ ടീമുകളൊന്നുമില്ല. System → Teams-ൽ അവ സൃഷ്ടിക്കുക, എന്നിട്ട് ഗ്രൂപ്പുകളെ ലിങ്ക് ചെയ്യാൻ തിരികെ വരിക.',
        'go_teams' => 'ടീമുകൾ തുറക്കുക',
        'claims_last_seen' => 'അവസാന സൈൻ-ഇൻ ({who}, {at}) അയച്ചത്: {groups}',
        'claims_none_sent' => 'ആ ഭാഗത്ത് ഒന്നുമില്ല',
        'claims_not_yet' => 'ഇത് സജ്ജമാക്കിയതിന് ശേഷം ആരും സൈൻ ഇൻ ചെയ്തിട്ടില്ല, അതിനാൽ തിരഞ്ഞെടുക്കാൻ ഗ്രൂപ്പുകളൊന്നുമില്ല. ഈ പ്രൊവൈഡർ വഴി ഒരു തവണ സൈൻ ഇൻ ചെയ്തിട്ട് തിരികെ വരിക.',
        'field_default_modules_hint' => 'JIT വഴി സൃഷ്ടിച്ച അനലിസ്റ്റുകൾക്ക് നൽകുന്ന, കോമയിട്ട് വേർതിരിച്ച മൊഡ്യൂൾ കീകൾ (ഉദാ. {example}). {strong} — പൈലറ്റുകൾക്കായി ഇത് സജ്ജമാക്കുക, അങ്ങനെ സ്വയം സൃഷ്ടിച്ച അനലിസ്റ്റുകൾ അഡ്മിൻ ആകില്ല.',
        'field_default_modules_strong' => 'ശൂന്യമായി വിട്ടാൽ അവർക്ക് എല്ലാ മൊഡ്യൂളിലേക്കും പൂർണ്ണ ആക്സസ് ലഭിക്കും',
        'field_default_modules_placeholder' => 'tickets, knowledge',
        'field_company' => 'കമ്പനി',
        'field_company_hint' => 'ഈ identity provider ഏത് ക്ലയന്റ് കമ്പനിയുടേതാണ് — അതിന്റെ requesters സെൽഫ്-സർവീസ് പോർട്ടലിൽ ഇവിടേക്ക് റൂട്ട് ചെയ്യപ്പെടും. MSP-internal provider-ന് (ഉദാ. അനലിസ്റ്റ് സൈൻ-ഇൻ) Global ആയി വിടുക.',
        'field_company_global' => 'Global (internal / all)',
        'field_portal_domains' => 'ഇമെയിൽ ഡൊമെയ്നുകൾ',
        'field_portal_domains_hint' => 'ഒരു വരിയിൽ ഒന്ന്, ഉദാ. company.com. പോർട്ടലിൽ, ഈ ഡൊമെയ്നുകളിലൊന്നിലുള്ള ഇമെയിൽ വിലാസം ആദ്യ തവണ പോലും നേരിട്ട് ഈ പ്രൊവൈഡറിലേക്ക് പോകും. ഇന്ന് പാസ്‌വേഡ് ഉപയോഗിച്ച് സൈൻ ഇൻ ചെയ്യുന്നവരും ഇതിൽ ഉൾപ്പെടും. മറ്റെല്ലാവർക്കും പതിവുപോലെ പാസ്‌വേഡ് ബോക്സ് ലഭിക്കും. ഒരു സബ്ഡൊമെയ്നിന് സ്വന്തം വരി വേണം. ആരെയും റൂട്ട് ചെയ്യാതിരിക്കാൻ ഒഴിച്ചിടുക.',
        'cb_portal_show_button' => 'പോർട്ടൽ ലോഗിനിൽ ബട്ടൺ കാണിക്കുക',
        'cb_portal_show_button_desc' => 'ഇമെയിൽ ബോക്സ് മാത്രമുള്ള പേജിനായി ടിക്ക് മാറ്റുക. മുകളിലെ ഡൊമെയ്നുകളിലുള്ളവർ അതിലൂടെ ഈ പ്രൊവൈഡറിൽ എത്തും. അനലിസ്റ്റ് ലോഗിനെ ഇത് ബാധിക്കില്ല.',
        'cancel' => 'റദ്ദാക്കുക',
