        'field_carddav_url' => 'സെർവറിന്റെ വിലാസം',
        'field_carddav_url_hint' => 'വെബ് പേജ് അല്ല, CardDAV പാത്ത്. Baïkal, Nextcloud അല്ലെങ്കിൽ മറ്റൊരു sabre/dav സെർവറിൽ ഇത് സാധാരണയായി https://dav.example.com/dav.php/addressbooks/jsmith/ പോലെയാണ് — നിങ്ങളുടെ address books ഉള്ള ലെവലിലേക്ക് ഇത് പോയിന്റ് ചെയ്യുക, Test connection അത് കണ്ടെത്തുന്നത് ലിസ്റ്റ് ചെയ്യും.',
        'field_carddav_username' => 'ഉപയോക്തൃനാമം',
