        'carddav_password_stored_hint' => 'ഒരു പാസ്‌വേഡ് സൂക്ഷിച്ചിട്ടുണ്ട്. അതേപടി നിലനിർത്താൻ ശൂന്യമായി വിടുക.',
        'field_carddav_auth' => 'Authentication',
        'field_carddav_auth_hint' => 'ഒരു കാരണവുമില്ലെങ്കിൽ ഇത് Automatic ആയി വിടുക. ഒരു സ്റ്റാൻഡേർഡ് Baïkal ഉൾപ്പെടെ മിക്ക സെർവറുകൾക്കും Basic-ന് പകരം Digest ആണ് വേണ്ടത് — Automatic സെർവറിനോട് ചോദിച്ച് അത് വാഗ്ദാനം ചെയ്യുന്നത് ഉപയോഗിക്കുന്നു.',
