        'field_carddav_book' => 'Address book',
        'field_carddav_book_hint' => 'ഏത് address book-ൽ നിന്ന് contacts വായിക്കണം. Test connection അമർത്തുക, നിങ്ങളുടെ അക്കൗണ്ടിന് കാണാൻ കഴിയുന്ന books ഇവിടെ നിറയും.',
        'carddav_book_untested' => 'നിങ്ങളുടെ address books കാണാൻ Test connection അമർത്തുക',
        'carddav_book_required' => 'ഒരു address book തിരഞ്ഞെടുക്കുക. ആദ്യം അവ ലിസ്റ്റ് ചെയ്യാൻ Test connection അമർത്തുക.',
        'carddav_url_required' => 'ആദ്യം നിങ്ങളുടെ CardDAV സെർവറിന്റെ വിലാസം നൽകുക.',
        'carddav_test' => 'Test connection',
        'carddav_test_desc' => 'FreeITSM-ന് സെർവറിലെത്താനും സൈൻ ഇൻ ചെയ്യാനും കഴിയുമോ എന്ന് പരിശോധിക്കുന്നു, കാണാൻ കഴിയുന്ന address books ലിസ്റ്റ് ചെയ്യുന്നു.',
        'carddav_test_desc_create' => 'ഈ വിശദാംശങ്ങൾ ഉപയോഗിച്ച് FreeITSM-ന് സെർവറിലെത്താനും സൈൻ ഇൻ ചെയ്യാനും കഴിയുമോ എന്ന് പരിശോധിക്കുന്നു.',
        'carddav_test_next' => 'ഇത് സേവ് ചെയ്യുക, എന്നിട്ട് ഒരു address book-ഉം ഏതൊക്കെ contacts കൊണ്ടുവരണമെന്നും തിരഞ്ഞെടുക്കാൻ അതിന്റെ വരിയിലെ settings ഐക്കൺ ഉപയോഗിക്കുക.',
        'carddav_page_sub' => 'ഒരു CardDAV address book. ഇതിലൂടെ ആരും സൈൻ ഇൻ ചെയ്യുന്നില്ല — ഇത് നിങ്ങളുടെ service desk-ലേക്ക് contacts കൊണ്ടുവരുന്നു.',
        'tab_contacts' => 'Contacts',
        'field_carddav_groups' => 'കൊണ്ടുവരേണ്ട Groups',
        'field_carddav_categories' => 'കൊണ്ടുവരേണ്ട Tags',
