        'hist_by' => 'ആരുടെ',
        'sync_heading' => 'ഈ directory-യിൽ നിന്ന് ആളുകളെ ഇംപോർട്ട് ചെയ്യുക',
        'sync_desc' => 'സൈൻ ഇൻ ചെയ്യുന്നത് ഒരാളെ അവർ ആദ്യം ലോഗിൻ ചെയ്യുമ്പോൾ മാത്രമേ സൃഷ്ടിക്കൂ. Importing എല്ലാവരെയും മുൻകൂട്ടി കൊണ്ടുവരുന്നു, അതിനാൽ ഒരിക്കലും സൈൻ ഇൻ ചെയ്യാത്ത ആളുകൾക്കുപോലും equipment നിയോഗിക്കാം.',
        'sync_enabled' => 'ഈ directory-യിൽ നിന്ന് ആളുകളെ ഇംപോർട്ട് ചെയ്യുക',
        'sync_base_dn_hint' => 'directory-യുടെ ഏത് ഭാഗത്ത് നിന്ന് ഇംപോർട്ട് ചെയ്യണം. സൈൻ-ഇൻ തിരയുന്ന അതേ സ്ഥലം ഉപയോഗിക്കാൻ ശൂന്യമായി വിടുക — മുഴുവൻ directory-ക്കും എതിരെ authenticate ചെയ്യുന്നു, പക്ഷേ അതിന്റെ ഒരു ഭാഗം മാത്രം ഇംപോർട്ട് ചെയ്യണമെങ്കിൽ ഇത് സെറ്റ് ചെയ്യുക.',
        'sync_base_dn_placeholder' => 'OU=Staff,OU=Company,DC=example,DC=com',
        'sync_filter_hint' => 'ഏതൊക്കെ entries ആളുകളായി കണക്കാക്കും. സ്ഥിരസ്ഥിതി സാധാരണ user അക്കൗണ്ടുകൾ കണ്ടെത്തുന്നു, മിക്കവാറും എപ്പോഴും ശരിയാണ്.',
        'sync_conflict' => 'ഒരാൾ ഇതിനകം ഇവിടെയുണ്ടെങ്കിൽ',
        'sync_conflict_hint' => 'അതേ ഇമെയിൽ വിലാസത്തോടെ FreeITSM-ൽ ഇതിനകം ഉള്ള ഒരാൾ directory-യിൽ ഉണ്ടെങ്കിൽ. Adopt ചെയ്യുന്നത് അവരെ directory-യിലേക്ക് ലിങ്ക് ചെയ്യുന്നു — അതിന് ശേഷം അവരുടെ FreeITSM portal പാസ്‌വേഡ് പ്രവർത്തിക്കില്ല, പകരം അവർ directory വഴി സൈൻ ഇൻ ചെയ്യും.',
        'sync_conflict_adopt' => 'അവരെ ഈ directory-യിലേക്ക് ലിങ്ക് ചെയ്യുക',
        'sync_conflict_flag' => 'അവരെ വെറുതെ വിട്ട് എനിക്കായി ഫ്ലാഗ് ചെയ്യുക',
        'sync_safety' => 'സുരക്ഷ',
        'sync_deactivate_hint' => 'directory-യിൽ നിന്ന് ഇത്രയും imports തുടർച്ചയായി കാണാതായ ശേഷം ഒരാളെ വിട്ടുപോയതായി അടയാളപ്പെടുത്തുക. ആരെയും ഒരിക്കലും ഇല്ലാതാക്കില്ല. ആളുകളെ ഒരിക്കലും സ്വയമേവ വിട്ടുപോയതായി അടയാളപ്പെടുത്താതിരിക്കാൻ 0 ആയി സെറ്റ് ചെയ്യുക.',
        'sync_brake_hint' => 'ഒരു ഇംപോർട്ട് കഴിഞ്ഞ തവണത്തേക്കാൾ ഇത്ര ശതമാനം കുറച്ച് ആളുകൾ കണ്ടെത്തിയാൽ ഒന്നും മാറ്റാതെ നിർത്തുക. തെറ്റായ ഒരു ക്രമീകരണമോ directory പ്രശ്നമോ എല്ലാവരും ഒരുമിച്ച് വിട്ടുപോകുന്നത് പോലെ കാണപ്പെടും, ഇത് നിങ്ങളുടെ ലിസ്റ്റ് ശൂന്യമാകുന്നത് തടയുന്നു. പരിശോധന ഓഫ് ചെയ്യാൻ 0 ആയി സെറ്റ് ചെയ്യുക.',
