        'map_hint_manager' => 'ഒരു directory entry ആയി വായിച്ച്, മറ്റെല്ലാവരെയും ഇംപോർട്ട് ചെയ്ത ശേഷം അത് ചൂണ്ടിക്കാണിക്കുന്ന വ്യക്തിയുമായി പൊരുത്തപ്പെടുത്തുന്നു.',
        'map_test_heading' => 'Mapping പരിശോധിക്കുക',
        'map_test_hint' => 'ഒരു യഥാർത്ഥ വ്യക്തിയെ വായിച്ച്, ഓരോ field-ഉം യഥാർത്ഥത്തിൽ എന്ത് ഇംപോർട്ട് ചെയ്യുമെന്ന് കാണിക്കുന്നു. ഒന്നും സേവ് ചെയ്യുന്നില്ല, ഒന്നും മാറുന്നില്ല. നിങ്ങൾക്കറിയാവുന്ന ഒരാളെ പരിശോധിക്കാൻ പേര് നൽകുക, അല്ലെങ്കിൽ ആദ്യം വരുന്നയാൾക്കായി ശൂന്യമായി വിടുക.',
        'map_test_sample' => 'പരിശോധിക്കേണ്ട ഒരാളുടെ സൈൻ-ഇൻ പേര് (ഓപ്ഷണൽ)',
        'map_test' => 'പരിശോധിക്കുക',
