        'map_empty' => 'അവിടെ ഒന്നുമില്ല',
        'map_result_ok' => '{name}-നെ വായിച്ചു. Map ചെയ്ത എല്ലാ field-ഉം ഒരു മൂല്യം കണ്ടെത്തി.',
        'map_result_skipped' => '{name}-നെ വായിച്ചു, പക്ഷേ ഒരു ഇംപോർട്ട് അവരെ ഒഴിവാക്കും: സൈൻ-ഇൻ പേരോ unique id-യോ ഒരു മൂല്യവും കണ്ടെത്തിയില്ല. ആദ്യം ആ രണ്ടെണ്ണം ശരിയാക്കുക — അവ പരിഹരിക്കുന്നത് വരെ മറ്റൊന്നും പ്രശ്നമല്ല.',
        'map_result_gaps' => '{name}-നെ വായിച്ചു. {n} map ചെയ്ത field(s) ഒന്നും കണ്ടെത്തിയില്ല — ഒന്നുകിൽ attribute പേര് തെറ്റാണ്, അല്ലെങ്കിൽ ഈ വ്യക്തിക്ക് അത് പൂരിപ്പിച്ചിട്ടില്ല. അവർക്ക് എന്തുണ്ടെന്ന് കാണാൻ താഴെയുള്ള ലിസ്റ്റ് തുറക്കുക.',
