        'entra_not_ready' => 'ഈ പേജ് ഉപയോഗിക്കുന്നതിന് മുമ്പ് ഡാറ്റാബേസ് വെരിഫിക്കേഷൻ (System → Database) പ്രവർത്തിപ്പിക്കുക: ക്രമീകരണങ്ങളുടെയും ഗ്രൂപ്പുകളുടെയും പട്ടികകൾ ഇതുവരെ നിലവിലില്ല.',
