        'entra_tenant' => 'Tenant ID',
        'entra_tenant_hint_detected' => 'ഇഷ്യറുടെ URL-ൽ നിന്ന് എടുത്തത് ({tenant}). മറ്റൊന്ന് വേണമെങ്കിൽ മാത്രം മാറ്റുക, അല്ലെങ്കിൽ ഒഴിച്ചിടുക.',
