        'entra_app_heading' => 'ഡയറക്ടറി വായിക്കുന്നത് ഏത് ആപ്പ് രജിസ്ട്രേഷൻ',
        'entra_app_hint' => 'സൈൻ-ഇൻ ആപ്പ് ഉപയോഗിക്കുന്നതാണ് ഏറ്റവും എളുപ്പം. പ്രത്യേക ആപ്പ് ഉപയോഗിച്ചാൽ, ഡയറക്ടറി മുഴുവനുമുള്ള Graph അനുമതികൾ എല്ലാ ഉപയോക്താക്കളും സൈൻ ഇൻ ചെയ്യുന്ന ആപ്പിൽ നിന്ന് അകന്നുനിൽക്കും.',
