        'entra_test' => 'കണക്ഷൻ പരിശോധിക്കുക',
        'entra_sync_desc' => 'ആരെങ്കിലും സൈൻ ഇൻ ചെയ്യുന്നതിന് മുമ്പുതന്നെ അവർ ഉണ്ടാകാനായി Entra ID-യിൽ നിന്ന് ആളുകളെ സൃഷ്ടിക്കുകയും അപ്ഡേറ്റ് ചെയ്യുകയും ചെയ്യുന്നു. ആരെയും ഒരിക്കലും ഇല്ലാതാക്കില്ല: പോകുന്നവരെ വിട്ടുപോയവരായി അടയാളപ്പെടുത്തും, പെട്ടെന്ന് വളരെ കുറച്ച് ആളുകളെ മാത്രം കണ്ടെത്തുന്ന റൺ ഒന്നും മാറ്റാതെ നിർത്തും. ഇംപോർട്ട് ചെയ്ത ആളുകൾക്ക് ഉടൻതന്നെ ഈ ദാതാവ് ഉപയോഗിച്ച് സൈൻ ഇൻ ചെയ്യാം.',
