        'sched_fallback' => 'സെർവറിൽ ഷെഡ്യൂൾ ചെയ്ത ടാസ്ക് ഒന്നും പ്രവർത്തിക്കുന്നില്ല, അതിനാൽ ഇംപോർട്ടുകൾ അനലിസ്റ്റുകളുടെ തുറന്ന പേജുകളിൽ നിന്നാണ് തുടങ്ങുന്നത്: ആരെങ്കിലും FreeITSM തുറന്നിരിക്കുമ്പോൾ മാത്രമേ അവ നടക്കൂ.',
        'sched_off' => 'ഓട്ടോമാറ്റിക് ഇംപോർട്ടുകൾ ഓഫ് ചെയ്തിരിക്കുന്നു: ആരെങ്കിലും Run അമർത്തുമ്പോൾ മാത്രമേ ഈ ഉറവിടം ഇംപോർട്ട് ചെയ്യൂ.',
        'sched_none' => 'ഈ ഉറവിടം സ്വയമേവ ഇംപോർട്ട് ചെയ്യുന്നതൊന്നുമില്ല: ഈ സെർവറിൽ ഷെഡ്യൂളർ പ്രവർത്തിക്കുന്നില്ല, ഫാൾബാക്കും ഓഫ് ആണ്.',
        'sched_source_off' => 'ഈ ഉറവിടമോ ഇംപോർട്ടിംഗോ ഓഫ് ആയിരിക്കുമ്പോൾ ഈ ഉറവിടം സ്വയമേവ ഇംപോർട്ട് ചെയ്യില്ല.',
        'sched_change' => 'Background jobs-ൽ ഇത് മാറ്റുക',
        'maint_page_title' => 'ഇംപോർട്ട് ചെയ്ത ആളുകൾ',
        'maint_page_sub' => 'ഒരു ഡയറക്ടറി ഉറവിടം - LDAP, ഒരു അഡ്രസ് ബുക്ക് അല്ലെങ്കിൽ Microsoft Entra ID - ഇംപോർട്ട് ചെയ്ത ആളുകൾ, ഒരു തീരുമാനം ആവശ്യമുള്ളപ്പോൾ: അവരുടെ ഉറവിടം ഇല്ലാതാക്കി, അത് ഇനി അവരെ കൊണ്ടുവരുന്നില്ല, അല്ലെങ്കിൽ അവരെ ഇംപോർട്ട് ചെയ്യാൻ പാടില്ലായിരുന്നു. ടിക്കറ്റുകളോ ഉപകരണങ്ങളോ ഉള്ള ആരെയും ഒരിക്കലും ഇല്ലാതാക്കില്ല, ഇവിടെ ചെയ്യുന്നതെല്ലാം സിസ്റ്റം ലോഗിൽ രേഖപ്പെടുത്തും.',
        'maint_source_heading' => 'ഒരു ഉറവിടം',
        'maint_source_label' => 'ഉറവിടം',
        'maint_deleted_kind' => 'ഇല്ലാതാക്കി',
        'maint_deleted_hint' => 'ഈ ഉറവിടം ഇല്ലാതാക്കിയതിനാൽ ഇത് ഇനി ആരെയും കൊണ്ടുവരുന്നില്ല. മറ്റൊരു ഉറവിടം ഇപ്പോൾ അവരെ അപ്ഡേറ്റ് ചെയ്ത് നിലനിർത്തുന്നില്ലെങ്കിൽ, ഇതിന്റെ ഇംപോർട്ടുകൾ സൃഷ്ടിച്ച ആളുകൾ താഴെ ലിസ്റ്റ് ചെയ്തിരിക്കുന്നു. ഇവിടെ നേരത്തെ ഉണ്ടായിരുന്ന ഒരാളുമായി പൊരുത്തപ്പെടുത്തിയവരെ ലിസ്റ്റ് ചെയ്യില്ല.',
        'maint_no_sources' => 'ഡയറക്ടറി ഉറവിടമൊന്നും സജ്ജീകരിച്ചിട്ടില്ല: ഇപ്പോഴും നിലവിലുള്ള ഒരു ഉറവിടവും ഇവിടെയുള്ള ആരെയും ഇംപോർട്ട് ചെയ്തിട്ടില്ല.',
        'maint_source_link' => 'ഈ ഉറവിടം ഇംപോർട്ട് ചെയ്ത ആളുകളെ പരിപാലിക്കുക',
        'maint_source_need_look' => 'ഈ ഉറവിടം ഇംപോർട്ട് ചെയ്ത ആളുകളിൽ {n} പേരെ {days} ദിവസമായി ഒരു ഇംപോർട്ടും കണ്ടെത്തിയിട്ടില്ല.',
        'maint_orphans_notice' => 'ഇല്ലാതാക്കിയ ഒരു ഉറവിടം ഇംപോർട്ട് ചെയ്ത {n} ആളുകളുണ്ട്.',
        'maint_orphans_review' => 'ഇംപോർട്ട് ചെയ്ത ആളുകളിൽ അവരെ അവലോകനം ചെയ്യുക',
        'maint_orphans_heading' => 'ഉറവിടം ഇല്ലാതാക്കിയ ആളുകൾ',
        'maint_orphans_desc' => 'ഇപ്പോൾ നിലവിലില്ലാത്ത ഒരു ഉറവിടം ഇംപോർട്ട് ചെയ്തവർ. ഒന്നും ഇനി അവരെ ലോക്ക് ചെയ്യുകയോ അപ്ഡേറ്റ് ചെയ്യുകയോ ചെയ്യുന്നില്ല; അവരെ സാധാരണ ആളുകളായി നിലനിർത്തണോ, വിട്ടുപോയവരായി അടയാളപ്പെടുത്തണോ, ഇല്ലാതാക്കണോ എന്ന് തീരുമാനിക്കുക.',
        'maint_stale_heading' => 'ഈ ഉറവിടം ഇനി കൊണ്ടുവരാത്ത ആളുകൾ',
        'maint_stale_hint' => 'ഓരോ ഇംപോർട്ടും ഓരോ വ്യക്തിയെയും അവസാനമായി കണ്ടെത്തിയ തീയതി രേഖപ്പെടുത്തുന്നു. ഈ ആളുകൾ ഇപ്പോഴും ഈ ഉറവിടത്തിന് നൽകിയിരിക്കുന്നു, എന്നാൽ നിങ്ങൾ തിരഞ്ഞെടുക്കുന്ന കാലയളവിൽ അത് അവരെ കണ്ടെത്തിയിട്ടില്ല: അവരെ ഡയറക്ടറിയിൽ നിന്ന് നീക്കിയിരിക്കാം, ഇംപോർട്ട് ചെയ്യുന്നതിന്റെ പരിധിക്ക് പുറത്തേക്ക് മാറ്റിയിരിക്കാം, അല്ലെങ്കിൽ ഇംപോർട്ട് പ്രവർത്തിക്കുന്നത് നിലച്ചിരിക്കാം. അവരെ വിട്ടുപോയവരായി അടയാളപ്പെടുത്തുക, ഈ ഉറവിടം ഇനി കൈകാര്യം ചെയ്യാത്ത സാധാരണ ആളുകളായി നിലനിർത്തുക, അല്ലെങ്കിൽ ഇല്ലാതാക്കുക.',
        'maint_remove_heading' => 'ഇംപോർട്ട് ചെയ്ത ആളുകളെ നീക്കം ചെയ്യുക',
        'maint_remove_hint' => 'നടക്കാൻ പാടില്ലാതിരുന്ന ഒരു ഇംപോർട്ട് പഴയപടിയാക്കുക: എല്ലാ ഇംപോർട്ടുകളിൽ നിന്നോ ഒന്നിൽ നിന്നോ ഈ ഉറവിടം സൃഷ്ടിച്ച ആളുകൾ. ഇവിടെ നേരത്തെ ഉണ്ടായിരുന്ന ഒരാളുമായി പൊരുത്തപ്പെടുത്തിയവർ ഒരിക്കലും ഈ ലിസ്റ്റിൽ വരില്ല, ടിക്കറ്റുകളോ ഉപകരണങ്ങളോ ഉള്ള ആരെയും നീക്കം ചെയ്യില്ല.',
        'maint_days_label' => 'ഇത്രയും ദിവസമായി ഇംപോർട്ട് കണ്ടെത്തിയിട്ടില്ല',
