        'maint_loading' => 'ലോഡ് ചെയ്യുന്നു...',
        'maint_source_imports' => 'ഈ ഉറവിടം ഇപ്പോഴും ഇംപോർട്ട് ചെയ്യുന്നു: നീക്കം ചെയ്യുന്ന ആരെയും അതിന്റെ അടുത്ത ഇംപോർട്ട് വീണ്ടും സൃഷ്ടിക്കും. ആദ്യം ഉറവിടമോ അതിന്റെ ഇംപോർട്ടോ ഓഫ് ചെയ്ത് സേവ് ചെയ്യുക.',
        'maint_source_imports_stale' => 'ഈ ഉറവിടം ഇപ്പോഴും ഇംപോർട്ട് ചെയ്യുന്നു: ഇല്ലാതാക്കുന്ന ആരെയും അതിന്റെ അടുത്ത ഇംപോർട്ട് വീണ്ടും സൃഷ്ടിക്കും. ആദ്യം ഉറവിടമോ അതിന്റെ ഇംപോർട്ടോ ഓഫ് ചെയ്ത് സേവ് ചെയ്യുക.',
