        'maint_do_hint_stale' => 'ആളുകളെ തിരഞ്ഞെടുക്കുക, തുടർന്ന് അവരെ എന്ത് ചെയ്യണമെന്ന് തിരഞ്ഞെടുക്കുക.',
        'maint_do_hint_imported' => 'ടിക്കറ്റുകളോ ഉപകരണങ്ങളോ ഉള്ള ആരെയും നീക്കം ചെയ്യില്ല: അവരെ ഒഴിവാക്കിയവരായി ലിസ്റ്റ് ചെയ്യും.',
