        'maint_confirm_keep' => '{n} ആളുകളെ ഇനി ഒരു ഡയറക്ടറിയും കൈകാര്യം ചെയ്യില്ല: എല്ലാ ഫീൽഡുകളും എഡിറ്റ് ചെയ്യാം, ഒരു ഇംപോർട്ടും അവരെ വീണ്ടും മാറ്റില്ല.',
        'maint_confirm_left_title' => 'വിട്ടുപോയവരായി അടയാളപ്പെടുത്തണോ?',
        'maint_confirm_left' => '{n} ആളുകളെ വിട്ടുപോയവരായി അടയാളപ്പെടുത്തും: Show leavers ടിക്ക് ചെയ്തിട്ടില്ലെങ്കിൽ People-ൽ മറയ്ക്കും. അവരുടെ ടിക്കറ്റുകളും ഉപകരണങ്ങളും ഉള്ളിടത്തുതന്നെ നിൽക്കും.',
        'maint_confirm_delete_title' => 'ഈ ആളുകളെ ഇല്ലാതാക്കണോ?',
        'maint_confirm_delete' => '{n} ആളുകളെ ഇല്ലാതാക്കും. ടിക്കറ്റുകളോ ഉപകരണങ്ങളോ മറ്റ് റെക്കോർഡുകളോ ഉള്ളവരെയോ ഇംപോർട്ടിന് മുമ്പ് ഇവിടെ ഉണ്ടായിരുന്നവരെയോ ഒഴിവാക്കും. ഇത് പഴയപടിയാക്കാനാകില്ല.',
        'maint_confirm_remove_title' => 'ഇംപോർട്ട് ചെയ്ത ആളുകളെ നീക്കം ചെയ്യണോ?',
        'maint_confirm_remove' => 'ഈ ഉറവിടം സൃഷ്ടിച്ച {n} ആളുകളെ ഇല്ലാതാക്കും. ടിക്കറ്റുകളോ ഉപകരണങ്ങളോ ഉള്ളവരെ ഒഴിവാക്കും. ഇത് പഴയപടിയാക്കാനാകില്ല.',
