        'entra_map_desc' => 'ഏത് Entra ആട്രിബ്യൂട്ട് FreeITSM-ലെ ഏത് വിശദാംശമാകുന്നു. ചാരനിറത്തിൽ കാണിച്ചിരിക്കുന്ന ആട്രിബ്യൂട്ട് (Entra സാധാരണ ഉപയോഗിക്കുന്നത്) ഉപയോഗിക്കാൻ ബോക്സ് ഒഴിച്ചിടുക. നിങ്ങൾ നൽകുന്ന ആട്രിബ്യൂട്ട് ഇംപോർട്ടിന്റെ അടുത്ത റണ്ണിൽ വായിക്കും.',
