        'entra_map_hint_manager' => 'Entra-യിലെ അവരുടെ മാനേജർ, അത് ചൂണ്ടുന്ന വ്യക്തിയുമായി പൊരുത്തപ്പെടുത്തിയത്. ഇത് ആട്രിബ്യൂട്ടല്ല, ഒരു ബന്ധമാണ്, അതിനാൽ മാപ്പ് ചെയ്യാനാകില്ല.',
        'entra_map_names_hint' => 'Microsoft Graph എഴുതുന്ന രീതിയിൽ പേര് ഉപയോഗിക്കുക. ഗ്രൂപ്പ് ചെയ്ത പ്രോപ്പർട്ടിക്കുള്ളിൽ ഒരു തലം വരെയും പ്രവർത്തിക്കും - onPremisesExtensionAttributes/extensionAttribute5, employeeOrgData/division - നിങ്ങളുടെ സ്വന്തം ഡയറക്ടറി എക്സ്റ്റൻഷനുകളും (extension_<app id>_<name>).',
