        'tp_intro' => 'ഒരു API കീ മോഷ്ടിക്കപ്പെട്ടതുപോലെ പെരുമാറുമ്പോൾ FreeITSM എന്ത് ചെയ്യുന്നു എന്നത്. ഓരോ അലേർട്ടും ബെല്ലിലൂടെയും ഇമെയിലിലൂടെയും (അയയ്ക്കാൻ കഴിയുന്ന ആദ്യ മെയിൽബോക്സിൽ നിന്ന്) അഡ്മിനിസ്ട്രേറ്റർമാർക്ക് പോകുന്നു, ഒരേ കീയ്ക്കും കാരണത്തിനും മണിക്കൂറിൽ പരമാവധി ഒരിക്കൽ, കൂടാതെ എല്ലാ അലേർട്ടും നിരസിക്കലും താഴെയുള്ള ലോഗിലുണ്ട്.',
