        'running_ok' => 'പശ്ചാത്തല വർക്കർ പ്രവർത്തിക്കുന്നു, ക്യൂ ഡെലിവർ ചെയ്യുന്നു.',
        'waiting_one' => '<strong>1</strong> webhook കാത്തിരിക്കുന്നു &mdash; അത് ഒരു മിനിറ്റിനുള്ളിൽ പുറത്തേക്ക് പോകും.',
        'waiting_many' => '<strong>{n}</strong> webhooks കാത്തിരിക്കുന്നു &mdash; അവ ഒരു മിനിറ്റിനുള്ളിൽ പുറത്തേക്ക് പോകും.',
        'nothing_waiting' => 'നിലവിൽ ഒന്നും കാത്തിരിക്കുന്നില്ല.',
        'never_explain' => 'പശ്ചാത്തല ഡെലിവറി വർക്കർ പ്രവർത്തിക്കാൻ ഷെഡ്യൂൾ ചെയ്യുന്നതുവരെ <strong>webhooks അയയ്ക്കില്ല</strong>.',
        'down_explain' => '<strong>webhooks ഇനി അയയ്ക്കുന്നില്ല</strong> &mdash; വർക്കർ അവസാനം പ്രവർത്തിച്ചത് {when}, അത് നിലച്ചതായി തോന്നുന്നു.',
        'stale_explain' => 'വർക്കർ പ്രവർത്തിക്കുന്നുണ്ട്, പക്ഷേ ഷെഡ്യൂളിനേക്കാൾ പിന്നിലാണ് (അവസാന റൺ {when}). ഇത് ഓരോ മിനിറ്റിലും പ്രവർത്തിക്കണം.',
        'queued_one' => '<strong>1</strong> webhook ക്യൂവിൽ കാത്തിരിക്കുന്നു.',
        'queued_many' => '<strong>{n}</strong> webhooks ക്യൂവിൽ കാത്തിരിക്കുന്നു.',
        'step1' => '<strong>ഡെലിവറി വർക്കർ ഓരോ മിനിറ്റിലും പ്രവർത്തിക്കാൻ ഷെഡ്യൂൾ ചെയ്യുക.</strong> സെർവറിൽ, ഒരു ഷെഡ്യൂൾ ചെയ്ത ടാസ്കിൽ നിന്ന് (Windows Task Scheduler) അല്ലെങ്കിൽ cron-ൽ നിന്ന് (Linux) ഈ കമാൻഡ് പ്രവർത്തിപ്പിക്കുക:',
        'step1_http' => 'ഷെല്ലിൽ നിന്ന് PHP പ്രവർത്തിപ്പിക്കാൻ കഴിയുന്നില്ലേ? പകരം HTTP വഴി അത് വിളിക്കുക (ഉദാ. ഒരു ഹോസ്റ്റഡ് cron സേവനത്തിൽ നിന്ന്):',
        'step2' => 'ഇവന്റുകൾ ക്യൂ നിറയ്ക്കാൻ തുടങ്ങേണ്ടതിന് <strong>ഒരു വർക്ക്ഫ്ലോയിലേക്ക് <em>Send a webhook</em> ആക്ഷൻ ചേർക്കുക</strong> &mdash; <a href="{url}">Workflows</a>-ന് കീഴിൽ.',
        'step3' => '<strong>ഈ പേജ് നിരീക്ഷിക്കുക.</strong> വർക്കർ ഒരിക്കൽ പ്രവർത്തിച്ചുകഴിഞ്ഞാൽ, മുകളിലെ നില പച്ചയാകും, ഡെലിവറികൾ താഴെ കാണിക്കും. പൂർണ്ണമായ സജ്ജീകരണ കുറിപ്പുകൾ (Windows &amp; Linux, signature verification) <a href="https://github.com/edmozley/freeitsm/wiki/Workflows" target="_blank" rel="noopener">Workflows വിക്കിയിൽ</a> ഉണ്ട്.',
        'fact_worker' => 'വർക്കർ സ്ക്രിപ്റ്റ്',
        'fact_retry' => 'റീട്രൈ ഷെഡ്യൂൾ',
        'fact_retry_sched' => '{schedule} &middot; {n} ശ്രമങ്ങൾക്ക് ശേഷം ഡെഡ്',
        'fact_retry_once' => 'വീണ്ടും ശ്രമിക്കില്ല &middot; 1 ശ്രമത്തിന് ശേഷം ഡെഡ്',
        'fact_retention' => 'ലോഗ് നിലനിർത്തൽ',
        'fact_queued' => 'ഇപ്പോൾ ക്യൂവിൽ',
        'days' => '{n} ദിവസം',
        'del_title' => 'ഡെലിവറി',
        'del_desc' => 'ഓരോ webhook-ഉം എത്തിക്കാൻ FreeITSM എത്രത്തോളം ശ്രമിക്കുന്നു.',
        'opt_default' => '{label} (സ്ഥിരസ്ഥിതി)',
        'del_attempts_label' => 'ഉപേക്ഷിക്കുന്നതിന് മുമ്പുള്ള ശ്രമങ്ങൾ',
        'del_attempts_one' => '1 ശ്രമം (വീണ്ടും ശ്രമിക്കില്ല)',
        'del_attempts_opt' => '{n} ശ്രമങ്ങൾ',
        'del_attempts_help' => 'പരാജയപ്പെട്ട ശ്രമം 1 മിനിറ്റിന് ശേഷം, പിന്നെ 5 മിനിറ്റ്, 15 മിനിറ്റ്, 1 മണിക്കൂർ, 6 മണിക്കൂർ എന്നിങ്ങനെ വീണ്ടും ശ്രമിക്കും, അതിന് ശേഷം ഓരോ 6 മണിക്കൂറിലും. അവസാന ശ്രമത്തിന് ശേഷം ഡെലിവറി <strong>Dead</strong> എന്ന് അടയാളപ്പെടുത്തി <em>Replay</em>-നായി കാത്തിരിക്കും. മാറ്റം ഇനി ക്യൂവിൽ വരുന്ന webhook-കൾക്ക് മാത്രം ബാധകമാണ് - ക്യൂവിലുള്ളവ തുടങ്ങിയ എണ്ണം തന്നെ നിലനിർത്തും.',
        'del_timeout_label' => 'എൻഡ്പോയിന്റ് മറുപടി നൽകാൻ കാത്തിരിക്കുക',
        'del_timeout_opt' => '{n} സെക്കൻഡ്',
        'del_timeout_help' => 'ഓരോ ശ്രമവും പരാജയമായി കണക്കാക്കുന്നതിന് മുമ്പ് എത്ര നേരം കാത്തിരിക്കുന്നു. വേഗത കുറവാണെന്ന് അറിയാവുന്ന എൻഡ്പോയിന്റിന് മാത്രം ഇത് കൂട്ടുക: വർക്കർ ഒരു സമയം ഒരു webhook മാത്രമേ അയയ്ക്കൂ, അതിനാൽ ദീർഘ കാത്തിരിപ്പ് ക്യൂവിലെ ബാക്കിയുള്ളവയെ വൈകിപ്പിക്കും. വർക്ക്ഫ്ലോ എഡിറ്ററിലെ <em>Send test</em> പരമാവധി 25 സെക്കൻഡ് കാത്തിരിക്കും.',
        'del_int_label' => 'അയയ്ക്കൽ പാതിവഴിയിൽ മുറിഞ്ഞാൽ',
        'del_int_retry' => 'വീണ്ടും ശ്രമിക്കുക - എൻഡ്പോയിന്റിന് രണ്ടുതവണ ലഭിച്ചേക്കാം',
        'del_int_stop' => 'നിർത്തുക, Replay-ക്കായി വിടുക',
        'del_int_help' => 'അയയ്ക്കുന്നതിനിടയിൽ വർക്കർ നിലച്ചാൽ - സെർവർ റീസ്റ്റാർട്ട്, അല്ലെങ്കിൽ ഷെഡ്യൂൾ ചെയ്ത ടാസ്ക് കില്ല് ചെയ്യപ്പെടൽ - എൻഡ്പോയിന്റിന് അത് ലഭിച്ചോ എന്ന് ആർക്കും അറിയില്ല. 10 മിനിറ്റിന് ശേഷം FreeITSM ഇത് തീർപ്പാക്കുന്നു: <strong>Try again</strong> ഇതിനെ പരാജയപ്പെട്ട ശ്രമമായി കണക്കാക്കി മുകളിലെ ഷെഡ്യൂൾ അനുസരിച്ച് വീണ്ടും ശ്രമിക്കുന്നു; <strong>Stop</strong> ഉടൻ തന്നെ ഇതിനെ Dead എന്ന് അടയാളപ്പെടുത്തുന്നു, അതിനാൽ നിങ്ങൾക്ക് എൻഡ്പോയിന്റ് പരിശോധിച്ച് സ്വയം Replay ചെയ്യാം. ഓരോ അയയ്ക്കലിലും <code>X-FreeITSM-Delivery</code> ഹെഡർ ഉണ്ട്, ഓരോ ശ്രമത്തിലും Replay-യിലും ഒരേ നമ്പറോടെ, അതിനാൽ നിങ്ങൾ സ്വയം പ്രവർത്തിപ്പിക്കുന്ന റിസീവറിന് ആവർത്തനം അവഗണിക്കാം. Slack, Teams പോലുള്ള ചാറ്റ് ടൂളുകൾക്ക് അതിന് കഴിയില്ല, സന്ദേശം രണ്ടുതവണ കാണിക്കും.',
        'dp_title' => 'ഡാറ്റ സംരക്ഷണം',
        'dp_desc' => 'നിങ്ങളുടെ webhooks-നെ കുറിച്ച് FreeITSM ഡിസ്കിൽ എന്ത് സൂക്ഷിക്കുന്നു, എത്ര കാലം സൂക്ഷിക്കുന്നു.',
        'enc_on_title' => 'Webhook URL-കളും സൈനിംഗ് സീക്രട്ടുകളും സൂക്ഷിക്കുമ്പോൾ എൻക്രിപ്റ്റ് ചെയ്യുന്നു',
        'enc_on_body' => 'വർക്ക്ഫ്ലോയിലും ഡെലിവറി ക്യൂവിലും AES-256-GCM ഉപയോഗിച്ചാണ് സൂക്ഷിക്കുന്നത്. ഒരു webhook URL സ്വയം തന്നെ ഒരു ക്രെഡൻഷ്യലാണ് &mdash; അത് കൈവശമുള്ള ആർക്കും നിങ്ങളുടെ ചാനലിലേക്ക് പോസ്റ്റ് ചെയ്യാം &mdash; ഒരു സന്ദേശം ശരിക്കും നിങ്ങളിൽ നിന്നാണ് വന്നതെന്ന് തെളിയിക്കുന്നത് സൈനിംഗ് സീക്രട്ടാണ്.',
        'enc_off_title' => 'എൻക്രിപ്ഷൻ കീ ഒന്നും ക്രമീകരിച്ചിട്ടില്ല &mdash; webhook URL-കളും സൈനിംഗ് സീക്രട്ടുകളും പ്ലെയിൻ ടെക്സ്റ്റായി സൂക്ഷിക്കുന്നു',
        'enc_off_body' => 'ഒരു എൻക്രിപ്ഷൻ കീ ഫയൽ ഉള്ളപ്പോൾ FreeITSM ഇവ എൻക്രിപ്റ്റ് ചെയ്യും, പക്ഷേ ഈ ഇൻസ്റ്റാളിൽ അതില്ല, അതിനാൽ നിങ്ങളുടെ webhooks പൂർണ്ണമായി പരാജയപ്പെടുത്തുന്നതിന് പകരം അവ ഉള്ളതുപോലെ സേവ് ചെയ്യുന്നു. ഡാറ്റാബേസോ അതിന്റെ ഒരു ബാക്കപ്പോ വായിക്കാൻ കഴിയുന്ന ആർക്കും നിങ്ങളുടെ ചാനലുകളിലേക്ക് പോസ്റ്റ് ചെയ്യാനും നിങ്ങളുടെ സിഗ്നേച്ചറുകൾ വ്യാജമായി ഉണ്ടാക്കാനും കഴിയും. എൻക്രിപ്ഷൻ കീ (<code>ENCRYPTION_KEY_PATH</code>) ക്രമീകരിച്ച ശേഷം, സൂക്ഷിച്ച മൂല്യങ്ങൾ എൻക്രിപ്റ്റ് ചെയ്യാൻ ഓരോ webhook വർക്ക്ഫ്ലോയും വീണ്ടും സേവ് ചെയ്യുക.',
        'ret_label' => 'അയച്ച പേലോഡുകൾ സൂക്ഷിക്കേണ്ട കാലം',
        'ret_none' => 'അവ ഒട്ടും സൂക്ഷിക്കരുത്',
        'ret_1' => '1 ദിവസം',
        'ret_7' => '7 ദിവസം (ശുപാർശ ചെയ്യുന്നു)',
        'ret_30' => '30 ദിവസം',
        'ret_forever' => 'ഡെലിവറി റെക്കോർഡ് നിലനിൽക്കുന്നിടത്തോളം',
        'ret_help' => 'അയച്ച കൃത്യമായ പേലോഡ് ഡെലിവറി ലോഗ് സൂക്ഷിക്കുന്നു. <strong>Full record</strong> ഫോർമാറ്റിൽ അത് ഒരു <strong>മുഴുവൻ ടിക്കറ്റാണ്</strong> &mdash; വിഷയം, അഭ്യർത്ഥിച്ചയാൾ, എല്ലാം &mdash; പ്ലെയിൻ ടെക്സ്റ്റായി ഇവിടെ പകർത്തിയിരിക്കുന്നു. ഇത്രയും ദിവസങ്ങൾക്ക് ശേഷം പേലോഡും പ്രതികരണ ബോഡികളും മായ്ക്കുന്നു, അതേസമയം ഡെലിവറി <em>റെക്കോർഡ്</em> (എൻഡ്‌പോയിന്റ്, നില, സമയം, പിശകുകൾ) മുകളിലെ ലോഗ് നിലനിർത്തൽ ({days} ദിവസം) ആ വരി പൂർണ്ണമായി നീക്കം ചെയ്യുന്നതുവരെ ഓഡിറ്റിനായി സൂക്ഷിക്കുന്നു.',
        'ret_tradeoff' => '<strong>ട്രേഡ്-ഓഫ്:</strong> <em>Replay</em> സൂക്ഷിച്ച പേലോഡ് വീണ്ടും അയയ്ക്കുന്നു, അതിനാൽ പേലോഡ് മായ്ച്ച ഒരു ഡെലിവറി ഇനി റീപ്ലേ ചെയ്യാനാകില്ല. ഒരു പരാജയത്തിന് ശേഷം മണിക്കൂറുകൾക്കുള്ളിലാണ് സാധാരണയായി Replay ഉപയോഗിക്കുന്നത്, ആഴ്ചകൾക്ക് ശേഷമല്ല.',
        'ov_title' => 'അവലോകനം',
