    'managers' => [
        'heading' => 'മാനേജർമാർ',
        'intro' => 'സെൽഫ്-സർവീസ് പോർട്ടലിൽ, തങ്ങൾ മാനേജ് ചെയ്യുന്നവർ ഉന്നയിച്ച ടിക്കറ്റുകൾ കാണാൻ കഴിയുന്ന ഒരാളാണ് മാനേജർ - ഉദാഹരണത്തിന് ഒരു വകുപ്പ് മേധാവി. അവർക്ക് പോർട്ടലിൽ ഒരു <strong>Team tickets</strong> ടാബ് ലഭിക്കും. സർവീസ് ഡെസ്കിനെ ഇത് ബാധിക്കില്ല.',
        'needs_verify' => 'ആദ്യം System → Database Verification പ്രവർത്തിപ്പിക്കുക. അത് പ്രവർത്തിപ്പിക്കുന്നതുവരെ, രഹസ്യ ടിക്കറ്റുകളെ വേർതിരിച്ചറിയാൻ കഴിയാത്തതിനാൽ ഇവിടെ എന്ത് സജ്ജമാക്കിയാലും മാനേജർമാർ ഓഫ് ആയിരിക്കും.',
        'on_heading' => 'പോർട്ടലിലെ മാനേജർമാർ',
        'enabled' => 'മാനേജർമാരെ അവരുടെ ടീമിന്റെ ടിക്കറ്റുകൾ കാണാൻ അനുവദിക്കുക',
        'enabled_desc' => 'നിങ്ങൾ ഓൺ ആക്കുന്നതുവരെ ഓഫ് ആണ്. ഇത് ഓഫ് ആയിരിക്കുമ്പോൾ താഴെയുള്ള ഒന്നിനും ഫലമില്ല.',
        'source_heading' => 'മാനേജർമാർ എവിടെ നിന്ന് വരുന്നു',
        'source_desc' => 'രണ്ട് ഉറവിടങ്ങൾ, രണ്ടും ഒരേസമയം. മാനേജ്മെന്റ് ലൈനുകൾ ഓരോ മാനേജർക്കും Tickets → Users അല്ലെങ്കിൽ Assets → Users-ലെ Manager access ബട്ടൺ ഉപയോഗിച്ച് സജ്ജമാക്കുന്നു.',
        'directory' => 'ഓരോ വ്യക്തിയുടെയും Manager ഫീൽഡ് ഉപയോഗിക്കുക',
        'directory_desc' => 'ഒരാളുടെ Manager ആയി സജ്ജമാക്കിയിരിക്കുന്നവർക്ക് - കൈകൊണ്ടായാലും ഡയറക്ടറിയിൽ നിന്നായാലും - അവരുടെ ടിക്കറ്റുകൾ കാണാം.',
        'depth' => 'എത്ര താഴെ വരെ',
        'depth_direct' => 'അവർക്ക് നേരിട്ട് റിപ്പോർട്ട് ചെയ്യുന്നവർ',
        'depth_all' => 'അവർക്ക് താഴെയുള്ള എല്ലാവരും, ഏറ്റവും താഴെ വരെ',
        'can_heading' => 'മാനേജർമാർക്ക് എന്തു ചെയ്യാം',
        'can_desc' => 'മാനേജർമാർക്ക് എപ്പോഴും അവരുടെ ടീമിന്റെ ടിക്കറ്റുകൾ വായിക്കാം. മറ്റെന്തൊക്കെ ചെയ്യാമെന്ന് ഓരോ ടിക്കറ്റിലും അവരെ അറിയിക്കും.',
        'can_reply' => 'അവരുടെ ടീമിന്റെ ടിക്കറ്റുകൾക്ക് മറുപടി നൽകുക',
        'can_close' => 'അവരുടെ ടീമിന്റെ ടിക്കറ്റുകൾ അടയ്ക്കുക',
        'conf_heading' => 'രഹസ്യ ടിക്കറ്റുകൾ',
        'conf_desc' => 'രഹസ്യം എന്ന് അടയാളപ്പെടുത്തിയ ടിക്കറ്റിൽ ഒരു മാനേജർ എന്ത് കാണുന്നു - HR-ലേക്ക് അയച്ച ഒരു രോഗനിർണയം, അല്ലെങ്കിൽ മാനേജർക്കെതിരെ തന്നെയുള്ള ഒരു പരാതി.',
        'conf_none' => 'ഒന്നും തന്നെയില്ല (ശുപാർശ ചെയ്യുന്നത്)',
        'conf_none_desc' => 'ടിക്കറ്റ് പൂർണ്ണമായും ഒഴിവാക്കും. അങ്ങനെ ഒന്നുണ്ടെന്ന് പോലും മാനേജർക്ക് അറിയാനാകില്ല.',
        'conf_stub' => 'ഒരു രഹസ്യ ടിക്കറ്റ് ഉണ്ടെന്ന വസ്തുത',
        'conf_stub_desc' => '"Confidential ticket" എന്ന പേരിൽ അതിന്റെ നമ്പറും നിലയും മാത്രം പട്ടികപ്പെടുത്തും, അതിലെ ഉള്ളടക്കം ഇല്ല. ഇത് മാത്രം ആരോ എന്തോ സ്വകാര്യമായി ഉന്നയിച്ചെന്ന് മാനേജറെ അറിയിച്ചേക്കാം എന്ന് ഓർക്കുക.',
        'conf_all' => 'എല്ലാം',
        'conf_all_desc' => 'രഹസ്യ ടിക്കറ്റുകൾ മറ്റേതൊരു ടിക്കറ്റും പോലെ കാണിക്കും. ഈ പോർട്ടൽ വഴി രഹസ്യമായ ഒന്നും ഒരിക്കലും ഉന്നയിക്കപ്പെടുന്നില്ലെങ്കിൽ മാത്രം ഇത് തിരഞ്ഞെടുക്കുക.',
        'notify_heading' => 'പുതിയ ടിക്കറ്റുകളെക്കുറിച്ച് മാനേജർമാരെ അറിയിക്കൽ',
        'notify_desc' => 'ഒരു മാനേജരുടെ ടീമിലെ ആരെങ്കിലും ടിക്കറ്റ് ഉന്നയിക്കുമ്പോൾ - എന്നാൽ രഹസ്യ ടിക്കറ്റ് പോലെ മാനേജർക്ക് തുറക്കാൻ അനുവാദമില്ലാത്തത് ഒരിക്കലുമില്ല.',
        'notify_none' => 'അറിയിക്കരുത് (സ്ഥിരസ്ഥിതി)',
        'notify_none_desc' => 'Team tickets നോക്കുമ്പോൾ മാനേജർമാർ പുതിയ ടിക്കറ്റുകൾ കാണും.',
        'notify_email' => 'ഇമെയിൽ അയയ്ക്കുക',
        'notify_email_desc' => 'ടിക്കറ്റിന്റെ നമ്പറും വിഷയവും അതിലേക്കുള്ള ലിങ്കും ഉള്ള ഒരു ഇമെയിൽ, ടിക്കറ്റ് മെയിൽബോക്സിൽ നിന്ന് മാനേജരുടെ വിലാസത്തിലേക്ക് അയയ്ക്കും. വിലാസമില്ലാത്ത മാനേജർമാർക്ക് ഒന്നും ലഭിക്കില്ല. ലിങ്കിന് പൊതു വെബ് വിലാസം ആവശ്യമാണ് (Tickets → Settings → Email Templates) - ഇല്ലെങ്കിൽ, ഇമെയിൽ വഴി വരുന്ന ടിക്കറ്റിന് പ്രവർത്തിക്കാത്ത ലിങ്കാണ് അയയ്ക്കുന്നത്.',
        'notify_bell' => 'പോർട്ടലിന്റെ അറിയിപ്പ് ബെല്ലിൽ',
        'notify_bell_desc' => 'പോർട്ടൽ ഹെഡറിൽ ഓരോ മാനേജർക്കുമുള്ള ബെല്ലിലേക്ക് - അനലിസ്റ്റുകൾക്കുള്ള അതേ ബെൽ. ഇമെയിലിനേക്കാൾ ശാന്തം: അവർ അടുത്ത തവണ സൈൻ ഇൻ ചെയ്യുമ്പോൾ അത് അവിടെ ഉണ്ടാകും.',
        'leavers_heading' => 'വിട്ടുപോയവർ',
        'leavers' => 'വിട്ടുപോയവരുടെ ടിക്കറ്റുകൾ കാണിക്കുന്നത് തുടരുക',
        'leavers_desc' => 'സ്ഥിരമായി ഓൺ ആണ്, അതിനാൽ ഒരാൾ വിടുമ്പോൾ തുറന്നിരിക്കുന്ന ടിക്കറ്റിന്റെ മേൽനോട്ടം തുടരും. വിട്ടുപോയ മാനേജർക്ക് എപ്പോഴും ആക്സസ് നഷ്ടപ്പെടും.',
        'edit_heading' => 'മാനേജ്മെന്റ് ലൈനുകൾ ആർക്ക് സജ്ജമാക്കാം',
        'edit_admins' => 'അഡ്മിനിസ്ട്രേറ്റർമാർ മാത്രം',
        'edit_people' => 'ആളുകളെ എഡിറ്റ് ചെയ്യാൻ കഴിയുന്ന അനലിസ്റ്റുകൾ',
        'edit_desc' => 'ഒരാൾക്ക് മാനേജർ ആക്സസ് നൽകുന്നത് മറ്റുള്ളവരുടെ ടിക്കറ്റുകൾ വായിക്കാൻ അവരെ അനുവദിക്കുന്നു, അതിനാൽ ഇത് കുറച്ചുപേരിൽ ഒതുക്കുന്നത് നല്ലതാണ്.',
        'saved' => 'സംരക്ഷിച്ചു',
        'save_failed' => 'സംരക്ഷിക്കാനായില്ല: {error}',
        'overview_heading' => 'മാനേജർമാർ',
        'overview_desc' => 'ആരെയെങ്കിലും മാനേജ് ചെയ്യുന്ന എല്ലാവരും, അവർക്ക് എത്ര പേരെ കാണാനാകും എന്നതോടെ - മാനേജർമാർ ഓൺ ആയിരുന്നെങ്കിൽ എന്ന മട്ടിൽ കണക്കാക്കിയത്, അതിനാൽ ഓൺ ആക്കുന്നതിന് മുമ്പ് പരിശോധിക്കാം.',
