        'none' => 'ഇതുവരെ ആരും ആരെയും മാനേജ് ചെയ്യുന്നില്ല.',
        'none_search' => 'ആ തിരയലുമായി ഒരു മാനേജരും പൊരുത്തപ്പെടുന്നില്ല.',
