        'self_close_desc' => 'പോർട്ടലിലെ ടിക്കറ്റിൽ ഒരു <strong>ഇനി ആവശ്യമില്ല</strong> ബട്ടൺ ചേർക്കുന്നു. റിക്വസ്റ്റർ ആണ് ക്ലോസ് ചെയ്തതെന്ന കുറിപ്പോടെയാണ് ടിക്കറ്റ് ക്ലോസ് ആകുന്നത്; അതിനാൽ താൻ തൊടാത്ത ഒന്ന് പരിഹരിച്ചതായി ഒരു അനലിസ്റ്റ് തോന്നിക്കുന്നതിനു പകരം, ആരാണ് ചെയ്തതെന്ന് ട്രെയിലിൽ കാണാം. ആരെങ്കിലും ഇപ്പോൾ ജോലി ചെയ്തുകൊണ്ടിരിക്കുന്ന ഒരു ടിക്കറ്റ്, അത് പരിഹരിച്ച് അവരുടെ സ്ഥിരീകരണം കാത്തിരിക്കുകയാണെങ്കിൽ, അവർക്ക് ക്ലോസ് ചെയ്യാനാകില്ല &mdash; അത് സ്ഥിരീകരിക്കേണ്ടത് അവരുടെ ജോലിയാണ്.',
