        'my_assets_desc' => 'ആ വ്യക്തിക്ക് അസൈൻ ചെയ്ത അസറ്റുകൾ കാണിക്കുന്ന ഒരു <strong>എന്റെ ഉപകരണങ്ങൾ</strong> പേജ് ചേർക്കുന്നു; അതുവഴി ഒരു സീരിയൽ നമ്പർ അറിയാൻ ടിക്കറ്റ് രജിസ്റ്റർ ചെയ്യേണ്ടി വരില്ല. കാണാൻ മാത്രം, അതും അവരുടേത് മാത്രം.',
