        'routing_hint' => 'മുകളിലുള്ള മെയിൽബോക്സുകളിൽ നിന്നും ഡൊമെയ്നുകളിൽ നിന്നും കണക്കാക്കിയ, റീഡ്-ഒൺലി സംഗ്രഹം. മറുപടികൾ എപ്പോഴും സന്ദേശം എത്തിയ അതേ മെയിൽബോക്സിൽ നിന്ന് പോകും.',
