        'support_label' => 'മറ്റ് കമ്പനികളെ പിന്തുണയ്ക്കുന്നു',
        'support_hint' => 'ഈ കമ്പനി മറ്റൊരു കമ്പനിക്ക് IT സപ്പോർട്ട് നൽകുമ്പോൾ ഇത് ഉപയോഗിക്കുക. ഓരോ വ്യക്തിയും ഇപ്പോഴും ഒരു കമ്പനിയിൽ തന്നെയാണ്. ഈ കമ്പനിയുടെ അനലിസ്റ്റുകൾക്ക് മറ്റേ കമ്പനിയിലേക്ക് ആക്സസ് ഉണ്ടെങ്കിൽ ഇവിടെ ഒന്നും ആവശ്യമില്ല - അപ്പോൾ അതിന്റെ ടിക്കറ്റുകൾ അവിടെ തന്നെ നിൽക്കും.',
