        'import_owner_html' => '<strong>ഉടമയും ഡെപ്യൂട്ടിയും:</strong> ഒരു <strong>Owner email</strong>, <strong>Owner group</strong> (People ഗ്രൂപ്പിന്റെ പേര്) അല്ലെങ്കിൽ <strong>Deputy email</strong> കോളം ഓരോ കോസ്റ്റ് സെന്ററിന്റെയും ഉത്തരവാദി ആരെന്ന് നിശ്ചയിക്കുന്നു. ആ കമ്പനിയിലെ ആരുമായും പൊരുത്തപ്പെടാത്ത വിലാസം ഇംപോർട്ട് നിർത്തുകയും പട്ടികയിൽ കാണിക്കുകയും ചെയ്യും. കോളങ്ങൾ ഒഴിവാക്കിയാൽ ഉടമകൾ അതേപടി തുടരും; ഒരു സെൽ ശൂന്യമാക്കിയാൽ ആ ഉടമയെ നീക്കും.',   // GH #160 Part B
