        'intro' => 'ഓരോ കമ്പനിക്കും നിങ്ങളുടെ ഫിനാൻസ് വകുപ്പ് ചെലവുകളും വരുമാനവും റിപ്പോർട്ട് ചെയ്യുന്ന അക്കൗണ്ടുകൾ - കോസ്റ്റ് സെന്ററിന്റെ "ആര്" എന്നതിനൊപ്പമുള്ള "എന്ത്". ഓരോ അക്കൗണ്ടിനും അത് എവിടെ കണക്കാക്കണമെന്ന് തീരുമാനിക്കുന്ന ഒരു തരമുണ്ട്: ചെലവ്, ഫിക്സഡ് അസറ്റ്, പേറോൾ അല്ലെങ്കിൽ വരുമാനം. അവ കൈകൊണ്ട് ചേർക്കാം, അല്ലെങ്കിൽ ഒരു സ്പ്രെഡ്ഷീറ്റ് ഇംപോർട്ട് ചെയ്തോ API വഴിയോ നിങ്ങളുടെ അക്കൗണ്ടിംഗ് സിസ്റ്റവുമായി ഒത്തുപോകുംവിധം സൂക്ഷിക്കാം. ഇനി ഉപയോഗിക്കാത്ത അക്കൗണ്ട് നിഷ്ക്രിയമാക്കാം: അതിലേക്ക് ഇതിനകം ചാർജ് ചെയ്തവയിൽ അത് തുടരും, പക്ഷേ പുതിയ ഒന്നിനും നൽകില്ല.',
