        'deleted' => 'അക്കൗണ്ട് ഇല്ലാതാക്കി',
        'delete_failed' => 'അക്കൗണ്ട് ഇല്ലാതാക്കാനായില്ല.',
        'import_title' => 'അക്കൗണ്ടുകൾ ഇംപോർട്ട് ചെയ്യുക',
        'import_help_html' => 'ആദ്യ വരി തലക്കെട്ടുകളായ ഒരു Excel വർക്ക്ബുക്ക് (.xlsx) അല്ലെങ്കിൽ CSV ഫയൽ ഉപയോഗിക്കുക. <strong>Code</strong> മാത്രമേ നിർബന്ധമുള്ളൂ; <strong>Name</strong>, <strong>Kind</strong> (Expense, Fixed asset, Payroll അല്ലെങ്കിൽ Income), <strong>Description</strong>, <strong>Parent code</strong>, <strong>Active</strong> (Yes അല്ലെങ്കിൽ No) എന്നിവ ഉണ്ടെങ്കിൽ ഉപയോഗിക്കും, മറ്റ് കോളങ്ങൾ അവഗണിക്കും. പുതിയ അക്കൗണ്ടിന് പേരും തരവും വേണം - അല്ലെങ്കിൽ തരം സ്വീകരിക്കുന്ന ഒരു പാരന്റ്. ലിസ്റ്റിൽ ഇതിനകമുള്ള കോഡുകൾ അപ്ഡേറ്റ് ചെയ്യും, പുതിയവ ചേർക്കും, ഒന്നും ഒരിക്കലും ഇല്ലാതാക്കില്ല. ലേഔട്ട് ശരിയാക്കാനുള്ള എളുപ്പവഴി ആദ്യം എക്സ്പോർട്ട് ചെയ്ത് ആ ഫയൽ എഡിറ്റ് ചെയ്യുക എന്നതാണ്.',
        'import_zeros_html' => '<strong>ആദ്യത്തെ പൂജ്യങ്ങൾ:</strong> ഒരു CSV Excel-ൽ തുറന്ന് വീണ്ടും സേവ് ചെയ്താൽ, ഫയൽ FreeITSM-ൽ എത്തുന്നതിന് മുമ്പ് Excel 0010 നെ 10 ആക്കി മാറ്റും. നിങ്ങളുടെ ലിസ്റ്റ് എഡിറ്റ് ചെയ്യാൻ Excel എക്സ്പോർട്ട് (.xlsx) ഉപയോഗിക്കുക - അതിലെ കോഡുകൾ ടെക്സ്റ്റായാണ് സൂക്ഷിക്കുന്നത്, അതിനാൽ പൂജ്യങ്ങൾ നിലനിൽക്കും.',
